const MAX_TASK_SLOTS: usize = 32;
const MAX_TASK_OPS: usize = 32;
const MAX_TASK_OUTPUTS: usize = 16;
const MAX_GROUP_TASKS: usize = 16;
const MAX_GROUP_SHARED_SLOTS: usize = 32;
const MAX_TASK_SHARED_INPUTS: usize = 16;
// Lowered from 8 to 3
const MIN_PARALLEL_TASKS: usize = 3;
// worker threads; caller adds one more lane
const WORKER_POOL_THREADS: usize = 7;
// spin hints between epoch reads; cuts contention
const WORKER_SPIN_BACKOFF: u32 = 32;
// Total epoch-checks a worker performs before parking
const WORKER_SPIN_BEFORE_PARK: u32 = 4096;

#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
pub static INVOKE_DBG_FAST: AtomicU64 = AtomicU64::new(0);
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
pub static INVOKE_DBG_FALLBACK: AtomicU64 = AtomicU64::new(0);
// dispatcher spins on remaining before park
const DISPATCHER_SPIN_BEFORE_PARK: u32 = 1024;
// Bounded park to recover from worker descheduling
const DISPATCHER_PARK_TIMEOUT_NS: u64 = 100_000; // 100us

static PARALLEL_BUDGET_LIMIT: OnceLock<u64> = OnceLock::new();
static PARALLEL_BUDGET_USED: AtomicU64 = AtomicU64::new(0);

fn force_parallel_runtime() -> bool {
    env::var("PAR_RUNTIME_FORCE_PARALLEL").ok().as_deref() == Some("1")
}

fn runtime_min_parallel_tasks() -> usize {
    // FORCE_PARALLEL allows 2 tasks; default 3
    if force_parallel_runtime() { 2 } else { MIN_PARALLEL_TASKS }
}

fn parallel_budget_limit() -> u64 {
    *PARALLEL_BUDGET_LIMIT.get_or_init(|| {
        env::var("PAR_RUNTIME_PARALLEL_BUDGET")
            .ok()
            .and_then(|value| value.parse::<u64>().ok())
            .unwrap_or(1024)
    })
}

fn parallel_budget_allows_execution() -> bool {
    if !force_parallel_runtime() {
        return true;
    }

    let limit = parallel_budget_limit();
    if limit == u64::MAX {
        return true;
    }

    loop {
        let used = PARALLEL_BUDGET_USED.load(Ordering::Relaxed);
        if used >= limit {
            return false;
        }
        if PARALLEL_BUDGET_USED
            .compare_exchange_weak(used, used + 1, Ordering::Relaxed, Ordering::Relaxed)
            .is_ok()
        {
            return true;
        }
    }
}

// raw u128 slots, half the enum size

type Slot = u128;
const SLOT_ZERO: Slot = 0;

// -- TaskOperation ----------------------------------------------------

#[derive(Clone, Copy)]
enum TaskOperation {
    Copy { dst: usize, src: usize },
    Unary { dst: usize, src: usize, apply: fn(&mut [Slot], usize, usize) },
    Binary { dst: usize, lhs: usize, rhs: usize, apply: fn(&mut [Slot], usize, usize, usize) },
    Cast { dst: usize, src: usize, apply: fn(&mut [Slot], usize, usize) },
}

// -- RuntimeTask ------------------------------------------------------

#[derive(Clone, Copy)]
struct RuntimeTask {
    slots: [Slot; MAX_TASK_SLOTS],
    slot_count: usize,
    ops: [TaskOperation; MAX_TASK_OPS],
    op_count: usize,
    outputs: [usize; MAX_TASK_OUTPUTS],
    output_count: usize,
    shared_input_slots: [usize; MAX_TASK_SHARED_INPUTS],
    shared_input_indices: [usize; MAX_TASK_SHARED_INPUTS],
    shared_input_count: usize,
}

impl Default for RuntimeTask {
    fn default() -> Self {
        Self {
            slots: [SLOT_ZERO; MAX_TASK_SLOTS],
            slot_count: 0,
            ops: [TaskOperation::Copy { dst: 0, src: 0 }; MAX_TASK_OPS],
            op_count: 0,
            outputs: [usize::MAX; MAX_TASK_OUTPUTS],
            output_count: 0,
            shared_input_slots: [usize::MAX; MAX_TASK_SHARED_INPUTS],
            shared_input_indices: [usize::MAX; MAX_TASK_SHARED_INPUTS],
            shared_input_count: 0,
        }
    }
}

impl RuntimeTask {
    fn init(&mut self, slot_count: usize, output_count: usize) {
        if slot_count > MAX_TASK_SLOTS || output_count > MAX_TASK_OUTPUTS {
            abort_parallel_runtime();
        }

        self.slot_count = slot_count;
        self.op_count = 0;
        self.output_count = output_count;
        self.shared_input_count = 0;
        self.slots[..slot_count].fill(SLOT_ZERO);
        self.outputs[..output_count].fill(usize::MAX);
        self.shared_input_slots.fill(usize::MAX);
        self.shared_input_indices.fill(usize::MAX);
    }

    fn set_output_slot(&mut self, output_index: usize, slot_index: usize) {
        if output_index >= self.output_count || slot_index >= self.slot_count {
            abort_parallel_runtime();
        }
        self.outputs[output_index] = slot_index;
    }

    #[inline(always)]
    fn set_input_raw(&mut self, slot_index: usize, value: Slot) {
        if slot_index >= self.slot_count {
            abort_parallel_runtime();
        }
        self.slots[slot_index] = value;
    }

    #[inline]
    fn set_input<T: ParallelScalar>(&mut self, slot_index: usize, value: T) {
        self.set_input_raw(slot_index, value.to_raw());
    }

    fn bind_shared_input(&mut self, slot_index: usize, shared_index: usize) {
        if slot_index >= self.slot_count || self.shared_input_count >= MAX_TASK_SHARED_INPUTS {
            abort_parallel_runtime();
        }
        self.shared_input_slots[self.shared_input_count] = slot_index;
        self.shared_input_indices[self.shared_input_count] = shared_index;
        self.shared_input_count += 1;
    }

    fn refresh_shared_inputs(&mut self, shared_slots: &[Slot]) {
        for input_index in 0..self.shared_input_count {
            let slot_index = self.shared_input_slots[input_index];
            let shared_index = self.shared_input_indices[input_index];
            if slot_index >= self.slot_count || shared_index >= shared_slots.len() {
                abort_parallel_runtime();
            }
            self.slots[slot_index] = shared_slots[shared_index];
        }
    }

    fn push_op(&mut self, op: TaskOperation) {
        if self.op_count >= MAX_TASK_OPS {
            abort_parallel_runtime();
        }
        self.ops[self.op_count] = op;
        self.op_count += 1;
    }

    fn execute_in_place(&mut self) {
        let stats_start = maybe_stats_start();
        if runtime_stats_enabled() {
            STATS.useful_task_compute_ops.fetch_add(self.op_count as u64, Ordering::Relaxed);
        }
        let slots = &mut self.slots[..self.slot_count];
        for op in &self.ops[..self.op_count] {
            match *op {
                TaskOperation::Copy { dst, src } => {
                    slots[dst] = slots[src];
                }
                TaskOperation::Unary { dst, src, apply } => apply(slots, dst, src),
                TaskOperation::Binary { dst, lhs, rhs, apply } => apply(slots, dst, lhs, rhs),
                TaskOperation::Cast { dst, src, apply } => apply(slots, dst, src),
            }
        }
        add_elapsed_ns(&STATS.useful_task_compute_ns, stats_start);
    }

    #[inline]
    fn get_output<T: ParallelScalar>(&self, output_index: usize) -> T {
        T::from_raw(self.get_output_raw(output_index))
    }

    #[inline(always)]
    fn get_output_raw(&self, output_index: usize) -> Slot {
        if output_index >= self.output_count {
            abort_parallel_runtime();
        }
        let slot_index = self.outputs[output_index];
        if slot_index == usize::MAX || slot_index >= self.slot_count {
            abort_parallel_runtime();
        }
        self.slots[slot_index]
    }
}

// lock-free persistent pool; epoch publishes, tickets claim

/// Park-state values for a worker
const WORKER_STATE_RUNNING: u32 = 0;
const WORKER_STATE_PARKING: u32 = 1; // about to call park, may already have
const WORKER_STATE_PARKED: u32 = 2;  // confirmed asleep, must unpark

#[repr(align(64))]
struct WorkerSlot {
    /// parker handle, set once at registration
    thread: OnceLock<Thread>,
    /// last epoch acted on; detects new dispatches
    seen_epoch: AtomicU64,
    /// park state; dispatcher unparks non-RUNNING only
    park_state: AtomicU32,
    /// pad to cache line, avoids false sharing
    _pad: [u8; 28],
}

impl WorkerSlot {
    const fn new() -> Self {
        Self {
            thread: OnceLock::new(),
            seen_epoch: AtomicU64::new(0),
            park_state: AtomicU32::new(WORKER_STATE_RUNNING),
            _pad: [0; 28],
        }
    }
}

#[repr(align(64))]
struct WorkerPool {
    /// dispatch counter; Release covers staging fields
    epoch: AtomicU64,
    /// single-flight CAS spin lock for dispatchers
    dispatch_in_flight: AtomicBool,
    /// dispatcher's task slice, valid during dispatch
    tasks_ptr: AtomicPtr<RuntimeTask>,
    /// Total tasks in the current dispatch.
    task_count: AtomicUsize,
    /// ticket counter; fetch_add claims a task
    next_task: AtomicUsize,
    /// Tasks still in flight
    remaining: AtomicUsize,
    /// Per-worker registration slots, plus their parker state.
    workers: [WorkerSlot; WORKER_POOL_THREADS],
    /// set once all workers registered; never cleared
    workers_ready: AtomicBool,
    _pad_tail: [u8; 32],
}

impl WorkerPool {
    const fn new() -> Self {
        Self {
            epoch: AtomicU64::new(0),
            dispatch_in_flight: AtomicBool::new(false),
            tasks_ptr: AtomicPtr::new(ptr::null_mut()),
            task_count: AtomicUsize::new(0),
            next_task: AtomicUsize::new(0),
            remaining: AtomicUsize::new(0),
            workers: [const { WorkerSlot::new() }; WORKER_POOL_THREADS],
            workers_ready: AtomicBool::new(false),
            _pad_tail: [0; 32],
        }
    }
}

// The pool is process-lifetime
static WORKER_POOL_STORAGE: WorkerPool = WorkerPool::new();
static WORKER_POOL_INIT: AtomicU8 = AtomicU8::new(0);

fn worker_pool() -> &'static WorkerPool {
    // Fast path: already initialized.
    if WORKER_POOL_INIT.load(Ordering::Acquire) == 2 {
        return &WORKER_POOL_STORAGE;
    }
    init_worker_pool()
}

#[cold]
fn init_worker_pool() -> &'static WorkerPool {
    // CAS wins init; losers wait
    match WORKER_POOL_INIT.compare_exchange(
        0,
        1,
        Ordering::AcqRel,
        Ordering::Acquire,
    ) {
        Ok(_) => {
            // We won the race: spawn workers.
            for worker_index in 0..WORKER_POOL_THREADS {
                let stats_on = runtime_stats_enabled();
                if stats_on {
                    STATS.spawned_thread_count.fetch_add(1, Ordering::Relaxed);
                }
                let _ = thread::Builder::new()
                    .name(format!("parallel-runtime-worker-{worker_index}"))
                    .spawn(move || worker_loop(&WORKER_POOL_STORAGE, worker_index));
            }
            // spin until all workers registered; brief
            loop {
                let mut all_ready = true;
                for slot in &WORKER_POOL_STORAGE.workers {
                    if slot.thread.get().is_none() {
                        all_ready = false;
                        break;
                    }
                }
                if all_ready {
                    break;
                }
                hint::spin_loop();
            }
            WORKER_POOL_STORAGE.workers_ready.store(true, Ordering::Release);
            WORKER_POOL_INIT.store(2, Ordering::Release);
        }
        Err(_) => {
            // Another thread is initializing; wait.
            while WORKER_POOL_INIT.load(Ordering::Acquire) != 2 {
                hint::spin_loop();
            }
        }
    }
    &WORKER_POOL_STORAGE
}

fn worker_loop(pool: &'static WorkerPool, worker_index: usize) {
    // register parker; slot owned by this worker
    let _ = pool.workers[worker_index].thread.set(thread::current());
    let slot = &pool.workers[worker_index];
    slot.park_state.store(WORKER_STATE_RUNNING, Ordering::Release);
    let mut local_epoch: u64 = 0;

    loop {
        // drain phase, pull tickets until exhausted
        let count = pool.task_count.load(Ordering::Acquire);
        let tasks_ptr = pool.tasks_ptr.load(Ordering::Acquire);
        if !tasks_ptr.is_null() && count != 0 {
            loop {
                let idx = pool.next_task.fetch_add(1, Ordering::AcqRel);
                if idx >= count {
                    break;
                }
                // SAFETY: Acquired epoch; unique idx, no aliasing
                unsafe { (&mut *tasks_ptr.add(idx)).execute_in_place(); }
                pool.remaining.fetch_sub(1, Ordering::AcqRel);
            }
            local_epoch = pool.epoch.load(Ordering::Acquire);
            slot.seen_epoch.store(local_epoch, Ordering::Release);
        }

        // spin phase; reread epoch every WORKER_SPIN_BACKOFF iters
        let mut checks = 0u32;
        let mut saw_new_epoch = false;
        loop {
            let cur = pool.epoch.load(Ordering::Acquire);
            if cur != local_epoch {
                local_epoch = cur;
                saw_new_epoch = true;
                break;
            }
            checks += 1;
            if checks >= WORKER_SPIN_BEFORE_PARK {
                break;
            }
            for _ in 0..WORKER_SPIN_BACKOFF {
                hint::spin_loop();
            }
        }
        if saw_new_epoch {
            continue; // re-enter drain loop
        }

        // park phase; mark PARKING, then recheck epoch
        slot.park_state.store(WORKER_STATE_PARKING, Ordering::SeqCst);
        let cur = pool.epoch.load(Ordering::Acquire);
        if cur != local_epoch {
            // Lost the race against a publisher
            slot.park_state.store(WORKER_STATE_RUNNING, Ordering::Release);
            local_epoch = cur;
            continue;
        }
        slot.park_state.store(WORKER_STATE_PARKED, Ordering::Release);
        let park_start = if runtime_stats_enabled() { Some(Instant::now()) } else { None };
        // Park until the dispatcher unparks us
        thread::park();
        slot.park_state.store(WORKER_STATE_RUNNING, Ordering::Release);
        add_elapsed_ns(&STATS.worker_condvar_wait_ns, park_start);
    }
}

/// Acquire the single-flight dispatcher slot
#[inline]
fn acquire_dispatch_slot(pool: &'static WorkerPool) {
    // Fast path: uncontended CAS.
    if pool.dispatch_in_flight
        .compare_exchange(false, true, Ordering::Acquire, Ordering::Relaxed)
        .is_ok()
    {
        return;
    }
    // Contended path: spin with hint::spin_loop.
    loop {
        if pool.dispatch_in_flight
            .compare_exchange_weak(false, true, Ordering::Acquire, Ordering::Relaxed)
            .is_ok()
        {
            return;
        }
        hint::spin_loop();
    }
}

#[inline]
fn release_dispatch_slot(pool: &'static WorkerPool) {
    pool.dispatch_in_flight.store(false, Ordering::Release);
}

fn execute_task_batch_on_worker_pool(tasks: &mut [RuntimeTask], start: usize, end: usize) {
    let task_count = end.saturating_sub(start);
    if task_count == 0 || task_count > MAX_GROUP_TASKS {
        abort_parallel_runtime();
    }

    let pool = worker_pool();
    let stats_on = runtime_stats_enabled();
    if stats_on {
        STATS.worker_submit_calls.fetch_add(1, Ordering::Relaxed);
        let bucket = log2_bucket(task_count);
        STATS.hist_parallel_batch_size[bucket].fetch_add(1, Ordering::Relaxed);
    }

    // -- Single-flight acquire -----------------------------------------
    let wait_start = if stats_on { Some(Instant::now()) } else { None };
    acquire_dispatch_slot(pool);
    if let Some(s) = wait_start {
        STATS.worker_mutex_wait_ns.fetch_add(s.elapsed().as_nanos() as u64, Ordering::Relaxed);
    }

    // -- Stage and publish ---------------------------------------------
    let hold_start = if stats_on { Some(Instant::now()) } else { None };
    let tasks_ptr = unsafe { tasks.as_mut_ptr().add(start) };
    pool.tasks_ptr.store(tasks_ptr, Ordering::Relaxed);
    pool.task_count.store(task_count, Ordering::Relaxed);
    pool.next_task.store(0, Ordering::Relaxed);
    pool.remaining.store(task_count, Ordering::Relaxed);
    // Release publishes staging stores to workers
    let new_epoch = pool.epoch.fetch_add(1, Ordering::Release).wrapping_add(1);
    if let Some(s) = hold_start {
        STATS.worker_mutex_hold_ns.fetch_add(s.elapsed().as_nanos() as u64, Ordering::Relaxed);
    }

    // wake only non-RUNNING workers; unpark is costly
    let workers_to_wake = task_count.saturating_sub(1).min(WORKER_POOL_THREADS);
    let dispatch_start = if stats_on { Some(Instant::now()) } else { None };
    for w in 0..workers_to_wake {
        let slot = &pool.workers[w];
        // Acquire orders this after worker's epoch check
        let st = slot.park_state.load(Ordering::Acquire);
        if st != WORKER_STATE_RUNNING {
            if let Some(t) = slot.thread.get() {
                t.unpark();
            }
        }
    }

    // -- Caller participates as a worker ------------------------------
    loop {
        let idx = pool.next_task.fetch_add(1, Ordering::AcqRel);
        if idx >= task_count {
            break;
        }
        // SAFETY: see worker_loop for the aliasing argument.
        unsafe { (&mut *tasks_ptr.add(idx)).execute_in_place(); }
        pool.remaining.fetch_sub(1, Ordering::AcqRel);
    }

    // wait for stragglers; spin, then bounded park
    let mut spin = 0u32;
    while pool.remaining.load(Ordering::Acquire) != 0 {
        if spin < DISPATCHER_SPIN_BEFORE_PARK {
            spin += 1;
            hint::spin_loop();
        } else {
            // no unpark arranged; time out and re-poll
            thread::park_timeout(Duration::from_nanos(DISPATCHER_PARK_TIMEOUT_NS));
        }
    }
    if let Some(s) = dispatch_start {
        STATS.worker_dispatch_ns.fetch_add(s.elapsed().as_nanos() as u64, Ordering::Relaxed);
    }

    // -- Cleanup + release --------------------------------------------
    let cleanup_start = if stats_on { Some(Instant::now()) } else { None };
    // tasks_ptr is dangling after this function returns
    pool.tasks_ptr.store(ptr::null_mut(), Ordering::Release);
    pool.task_count.store(0, Ordering::Release);
    release_dispatch_slot(pool);
    if let Some(s) = cleanup_start {
        STATS.worker_cleanup_ns.fetch_add(s.elapsed().as_nanos() as u64, Ordering::Relaxed);
    }

    // Suppress unused warnings on cold paths.
    let _ = new_epoch;
}

// -- RuntimeGroup -----------------------------------------------------

struct RuntimeGroup {
    tasks: [RuntimeTask; MAX_GROUP_TASKS],
    shared_slots: [Slot; MAX_GROUP_SHARED_SLOTS],
    shared_slot_count: usize,
    task_count: usize,
    max_parallelism: usize,
    shape_id: usize,
    executed: bool,
    cached: bool,
    building_shape: bool,
    in_use: bool,
}

impl RuntimeGroup {
    fn new(task_count: usize, max_parallelism: usize) -> Self {
        if task_count > MAX_GROUP_TASKS {
            abort_parallel_runtime();
        }
        Self {
            tasks: [RuntimeTask::default(); MAX_GROUP_TASKS],
            shared_slots: [SLOT_ZERO; MAX_GROUP_SHARED_SLOTS],
            shared_slot_count: 0,
            task_count,
            max_parallelism: max_parallelism.max(1),
            shape_id: 0,
            executed: false,
            cached: false,
            building_shape: true,
            in_use: true,
        }
    }

    fn new_cached(shape_id: usize, task_count: usize, max_parallelism: usize) -> Self {
        let mut group = Self::new(task_count, max_parallelism);
        group.shape_id = shape_id;
        group.cached = true;
        group
    }

    fn prepare_cached_iteration(&mut self, task_count: usize, max_parallelism: usize) {
        if task_count > MAX_GROUP_TASKS {
            abort_parallel_runtime();
        }
        self.task_count = task_count;
        self.max_parallelism = max_parallelism.max(1);
        self.executed = false;
        self.in_use = true;
        self.building_shape = !self.building_shape_is_complete();
    }

    fn begin_iteration(&mut self) {
        self.executed = false;
    }

    fn init_shared_inputs(&mut self, shared_slot_count: usize) {
        if shared_slot_count > MAX_GROUP_SHARED_SLOTS {
            abort_parallel_runtime();
        }
        if self.building_shape {
            self.shared_slot_count = shared_slot_count;
            self.shared_slots[..shared_slot_count].fill(SLOT_ZERO);
        }
    }

    fn building_shape_is_complete(&self) -> bool {
        self.cached && !self.building_shape
    }

    fn task_mut(&mut self, task_index: usize) -> &mut RuntimeTask {
        if task_index >= self.task_count {
            abort_parallel_runtime();
        }
        &mut self.tasks[task_index]
    }

    fn task_ref(&self, task_index: usize) -> &RuntimeTask {
        if task_index >= self.task_count {
            abort_parallel_runtime();
        }
        &self.tasks[task_index]
    }

    fn set_shared_input_raw(&mut self, shared_index: usize, value: Slot) {
        if shared_index >= self.shared_slot_count {
            abort_parallel_runtime();
        }
        self.shared_slots[shared_index] = value;
    }

    fn refresh_shared_inputs(&mut self) {
        let shared_slots = &self.shared_slots[..self.shared_slot_count];
        for task in &mut self.tasks[..self.task_count] {
            task.refresh_shared_inputs(shared_slots);
        }
    }

    fn execute(&mut self) {
        if self.executed {
            return;
        }

        let stats_on = runtime_stats_enabled();
        let task_count = self.task_count;
        // record task histogram and total ops
        if stats_on {
            let bucket = log2_bucket(task_count);
            STATS.hist_tasks_per_execute[bucket].fetch_add(1, Ordering::Relaxed);
            STATS.total_tasks_in_executed_groups
                .fetch_add(task_count as u64, Ordering::Relaxed);
            let op_sum: usize = self.tasks[..task_count].iter().map(|t| t.op_count).sum();
            STATS.total_ops_in_executed_groups.fetch_add(op_sum as u64, Ordering::Relaxed);
            let output_sum: usize =
                self.tasks[..task_count].iter().map(|t| t.output_count).sum();
            STATS.total_outputs_in_executed_groups
                .fetch_add(output_sum as u64, Ordering::Relaxed);
            STATS.total_shared_inputs_refreshed
                .fetch_add(self.shared_slot_count as u64, Ordering::Relaxed);
        }

        // First-iteration detection for cached groups
        let first_iteration = self.cached && self.building_shape;

        let refresh_start = if stats_on { Some(Instant::now()) } else { None };
        self.refresh_shared_inputs();
        if let Some(s) = refresh_start {
            STATS.shared_input_refresh_ns
                .fetch_add(s.elapsed().as_nanos() as u64, Ordering::Relaxed);
        }

        let min_parallel_tasks = runtime_min_parallel_tasks();
        if task_count < min_parallel_tasks
            || self.max_parallelism <= 1
            || !parallel_budget_allows_execution()
        {
            let seq_start = if stats_on { Some(Instant::now()) } else { None };
            if stats_on {
                if task_count < min_parallel_tasks {
                    STATS.sequential_due_task_count.fetch_add(1, Ordering::Relaxed);
                } else {
                    STATS.sequential_due_max_parallelism.fetch_add(1, Ordering::Relaxed);
                }
            }
            for task in &mut self.tasks[..task_count] {
                task.execute_in_place();
            }
            self.executed = true;
            if let Some(s) = seq_start {
                let ns = s.elapsed().as_nanos() as u64;
                STATS.sequential_execute_ns.fetch_add(ns, Ordering::Relaxed);
                if first_iteration {
                    STATS.first_iteration_execute_ns.fetch_add(ns, Ordering::Relaxed);
                    STATS.first_iteration_execute_calls.fetch_add(1, Ordering::Relaxed);
                }
            }
            if self.cached {
                self.building_shape = false;
            }
            return;
        }

        let par_start = if stats_on { Some(Instant::now()) } else { None };
        if stats_on {
            STATS.parallel_path_taken.fetch_add(1, Ordering::Relaxed);
        }
        let mut batch_start = 0usize;
        while batch_start < task_count {
            let batch_end = (batch_start + self.max_parallelism).min(task_count);
            if stats_on {
                STATS.parallel_batch_count.fetch_add(1, Ordering::Relaxed);
            }
            execute_task_batch_on_worker_pool(
                &mut self.tasks[..task_count],
                batch_start,
                batch_end,
            );
            if stats_on {
                STATS.join_count.fetch_add(1, Ordering::Relaxed);
            }
            batch_start = batch_end;
        }

        self.executed = true;
        if let Some(s) = par_start {
            let ns = s.elapsed().as_nanos() as u64;
            STATS.parallel_execute_ns.fetch_add(ns, Ordering::Relaxed);
            if first_iteration {
                STATS.first_iteration_execute_ns.fetch_add(ns, Ordering::Relaxed);
                STATS.first_iteration_execute_calls.fetch_add(1, Ordering::Relaxed);
            }
        }
        if self.cached {
            self.building_shape = false;
        }
    }
}

// -- Thread-local group cache -----------------------------------------

const GROUP_CACHE_CAP: usize = 256;
const GROUP_CACHE_PROBE_LIMIT: usize = 8;
const GROUP_CACHE_MASK: usize = GROUP_CACHE_CAP - 1;

#[derive(Clone, Copy)]
struct GroupCacheEntry {
    shape_id: usize, // 0 = empty slot
    handle: usize,
}

struct GroupCache {
    entries: [GroupCacheEntry; GROUP_CACHE_CAP],
}

impl GroupCache {
    const fn new() -> Self {
        Self { entries: [GroupCacheEntry { shape_id: 0, handle: 0 }; GROUP_CACHE_CAP] }
    }
}

crate::thread_local! {
    static GROUP_CACHE: UnsafeCell<GroupCache> = const { UnsafeCell::new(GroupCache::new()) };
}

#[inline]
fn with_group_cache<R>(f: impl FnOnce(&mut GroupCache) -> R) -> R {
    GROUP_CACHE.with(|cell| {
        // SAFETY: thread-local cell, no other borrows
        let cache = unsafe { &mut *cell.get() };
        f(cache)
    })
}

fn mix_shape_id(shape_id: usize) -> usize {
    let mut h = shape_id;
    h ^= h >> 33;
    h = h.wrapping_mul(0xff51_afd7_ed55_8ccdusize);
    h ^= h >> 33;
    h
}

// raw u128 storage; LLVM folds the conversions

trait ParallelScalar: Copy + Send + 'static {
    fn to_raw(self) -> Slot;
    fn from_raw(raw: Slot) -> Self;
}

trait ParallelUnaryOp: ParallelScalar {
    fn apply_unary(op_kind: u8, value: Self) -> Self;
}

trait ParallelBinaryOp: ParallelScalar {
    fn apply_binary(op_kind: u8, lhs: Self, rhs: Self) -> Self;
}

trait ParallelCompareOp: ParallelScalar {
    fn apply_compare(op_kind: u8, lhs: Self, rhs: Self) -> bool;
}

trait ParallelCastFrom<Src>: ParallelScalar {
    fn parallel_cast_from(value: Src) -> Self;
}

const UNARY_OP_NOT: u8 = 0;
const UNARY_OP_NEG: u8 = 1;

const BINARY_OP_ADD: u8 = 0;
const BINARY_OP_SUB: u8 = 1;
const BINARY_OP_MUL: u8 = 2;
const BINARY_OP_BIT_AND: u8 = 3;
const BINARY_OP_BIT_OR: u8 = 4;
const BINARY_OP_BIT_XOR: u8 = 5;

const COMPARE_OP_EQ: u8 = 0;
const COMPARE_OP_NE: u8 = 1;
const COMPARE_OP_LT: u8 = 2;
const COMPARE_OP_LE: u8 = 3;
const COMPARE_OP_GT: u8 = 4;
const COMPARE_OP_GE: u8 = 5;

// -- ParallelScalar impls ---------------------------------------------

// integers round-trip losslessly via `as`
macro_rules! impl_parallel_scalar_int {
    ($($ty:ty),+ $(,)?) => {
        $(
            impl ParallelScalar for $ty {
                #[inline(always)]
                fn to_raw(self) -> Slot { self as Slot }
                #[inline(always)]
                fn from_raw(raw: Slot) -> Self { raw as $ty }
            }
        )+
    };
}

impl_parallel_scalar_int!(u8, u16, u32, u64, u128, usize, i8, i16, i32, i64, i128, isize);

impl ParallelScalar for bool {
    #[inline(always)]
    fn to_raw(self) -> Slot {
        self as Slot
    }
    #[inline(always)]
    fn from_raw(raw: Slot) -> Self {
        raw != 0
    }
}

impl ParallelScalar for char {
    #[inline(always)]
    fn to_raw(self) -> Slot {
        self as Slot
    }
    #[inline(always)]
    fn from_raw(raw: Slot) -> Self {
        // SAFETY: compiler only stores valid chars
        unsafe { char::from_u32_unchecked(raw as u32) }
    }
}

// Unary / binary / compare op impls

macro_rules! impl_parallel_binary_int {
    ($($ty:ty),+ $(,)?) => {
        $(
            impl ParallelBinaryOp for $ty {
                fn apply_binary(op_kind: u8, lhs: Self, rhs: Self) -> Self {
                    match op_kind {
                        BINARY_OP_ADD => lhs.wrapping_add(rhs),
                        BINARY_OP_SUB => lhs.wrapping_sub(rhs),
                        BINARY_OP_MUL => lhs.wrapping_mul(rhs),
                        BINARY_OP_BIT_AND => lhs & rhs,
                        BINARY_OP_BIT_OR => lhs | rhs,
                        BINARY_OP_BIT_XOR => lhs ^ rhs,
                        _ => abort_parallel_runtime(),
                    }
                }
            }

            impl ParallelCompareOp for $ty {
                fn apply_compare(op_kind: u8, lhs: Self, rhs: Self) -> bool {
                    match op_kind {
                        COMPARE_OP_EQ => lhs == rhs,
                        COMPARE_OP_NE => lhs != rhs,
                        COMPARE_OP_LT => lhs < rhs,
                        COMPARE_OP_LE => lhs <= rhs,
                        COMPARE_OP_GT => lhs > rhs,
                        COMPARE_OP_GE => lhs >= rhs,
                        _ => abort_parallel_runtime(),
                    }
                }
            }
        )+
    };
}

macro_rules! impl_parallel_unary_signed {
    ($($ty:ty),+ $(,)?) => {
        $(
            impl ParallelUnaryOp for $ty {
                fn apply_unary(op_kind: u8, value: Self) -> Self {
                    match op_kind {
                        UNARY_OP_NOT => !value,
                        UNARY_OP_NEG => value.wrapping_neg(),
                        _ => abort_parallel_runtime(),
                    }
                }
            }
        )+
    };
}

macro_rules! impl_parallel_unary_unsigned {
    ($($ty:ty),+ $(,)?) => {
        $(
            impl ParallelUnaryOp for $ty {
                fn apply_unary(op_kind: u8, value: Self) -> Self {
                    match op_kind {
                        UNARY_OP_NOT => !value,
                        _ => abort_parallel_runtime(),
                    }
                }
            }
        )+
    };
}

macro_rules! impl_parallel_casts_from {
    ($src:ty => $($dst:ty),+ $(,)?) => {
        $(
            impl ParallelCastFrom<$src> for $dst {
                fn parallel_cast_from(value: $src) -> Self {
                    value as Self
                }
            }
        )+
    };
}

impl ParallelUnaryOp for bool {
    fn apply_unary(op_kind: u8, value: Self) -> Self {
        match op_kind {
            UNARY_OP_NOT => !value,
            _ => abort_parallel_runtime(),
        }
    }
}

impl ParallelBinaryOp for bool {
    fn apply_binary(op_kind: u8, lhs: Self, rhs: Self) -> Self {
        match op_kind {
            BINARY_OP_BIT_AND => lhs & rhs,
            BINARY_OP_BIT_OR => lhs | rhs,
            BINARY_OP_BIT_XOR => lhs ^ rhs,
            _ => abort_parallel_runtime(),
        }
    }
}

impl ParallelCompareOp for bool {
    fn apply_compare(op_kind: u8, lhs: Self, rhs: Self) -> bool {
        match op_kind {
            COMPARE_OP_EQ => lhs == rhs,
            COMPARE_OP_NE => lhs != rhs,
            _ => abort_parallel_runtime(),
        }
    }
}

impl ParallelCompareOp for char {
    fn apply_compare(op_kind: u8, lhs: Self, rhs: Self) -> bool {
        match op_kind {
            COMPARE_OP_EQ => lhs == rhs,
            COMPARE_OP_NE => lhs != rhs,
            COMPARE_OP_LT => lhs < rhs,
            COMPARE_OP_LE => lhs <= rhs,
            COMPARE_OP_GT => lhs > rhs,
            COMPARE_OP_GE => lhs >= rhs,
            _ => abort_parallel_runtime(),
        }
    }
}

impl_parallel_binary_int!(u8, u16, u32, u64, u128, usize, i8, i16, i32, i64, i128, isize);
impl_parallel_unary_unsigned!(u8, u16, u32, u64, u128, usize);
impl_parallel_unary_signed!(i8, i16, i32, i64, i128, isize);
impl_parallel_casts_from!(u8 => u8, u16, u32, u64, u128, usize, i8, i16, i32, i64, i128, isize);
impl_parallel_casts_from!(u16 => u8, u16, u32, u64, u128, usize, i8, i16, i32, i64, i128, isize);
impl_parallel_casts_from!(u32 => u8, u16, u32, u64, u128, usize, i8, i16, i32, i64, i128, isize);
impl_parallel_casts_from!(u64 => u8, u16, u32, u64, u128, usize, i8, i16, i32, i64, i128, isize);
impl_parallel_casts_from!(u128 => u8, u16, u32, u64, u128, usize, i8, i16, i32, i64, i128, isize);
impl_parallel_casts_from!(usize => u8, u16, u32, u64, u128, usize, i8, i16, i32, i64, i128, isize);
impl_parallel_casts_from!(i8 => u8, u16, u32, u64, u128, usize, i8, i16, i32, i64, i128, isize);
impl_parallel_casts_from!(i16 => u8, u16, u32, u64, u128, usize, i8, i16, i32, i64, i128, isize);
impl_parallel_casts_from!(i32 => u8, u16, u32, u64, u128, usize, i8, i16, i32, i64, i128, isize);
impl_parallel_casts_from!(i64 => u8, u16, u32, u64, u128, usize, i8, i16, i32, i64, i128, isize);
impl_parallel_casts_from!(i128 => u8, u16, u32, u64, u128, usize, i8, i16, i32, i64, i128, isize);
impl_parallel_casts_from!(isize => u8, u16, u32, u64, u128, usize, i8, i16, i32, i64, i128, isize);

// apply helpers on raw Slot arrays

fn apply_unary<T: ParallelUnaryOp>(slots: &mut [Slot], dst: usize, src: usize) {
    let value = T::from_raw(slots[src]);
    slots[dst] = T::apply_unary(UNARY_OP_NOT, value).to_raw();
}

fn apply_unary_neg<T: ParallelUnaryOp>(slots: &mut [Slot], dst: usize, src: usize) {
    let value = T::from_raw(slots[src]);
    slots[dst] = T::apply_unary(UNARY_OP_NEG, value).to_raw();
}

fn apply_binary<T: ParallelBinaryOp>(
    op_kind: u8,
    slots: &mut [Slot],
    dst: usize,
    lhs: usize,
    rhs: usize,
) {
    let lhs = T::from_raw(slots[lhs]);
    let rhs = T::from_raw(slots[rhs]);
    slots[dst] = T::apply_binary(op_kind, lhs, rhs).to_raw();
}

fn apply_compare<T: ParallelCompareOp>(
    op_kind: u8,
    slots: &mut [Slot],
    dst: usize,
    lhs: usize,
    rhs: usize,
) {
    let lhs = T::from_raw(slots[lhs]);
    let rhs = T::from_raw(slots[rhs]);
    slots[dst] = T::apply_compare(op_kind, lhs, rhs).to_raw();
}

fn apply_cast<Src, Dst>(slots: &mut [Slot], dst: usize, src: usize)
where
    Src: ParallelScalar,
    Dst: ParallelScalar + ParallelCastFrom<Src>,
{
    let value = Src::from_raw(slots[src]);
    slots[dst] = Dst::parallel_cast_from(value).to_raw();
}

fn binary_dispatch<T: ParallelBinaryOp>(op_kind: u8) -> fn(&mut [Slot], usize, usize, usize) {
    match op_kind {
        BINARY_OP_ADD => {
            |slots, dst, lhs, rhs| apply_binary::<T>(BINARY_OP_ADD, slots, dst, lhs, rhs)
        }
        BINARY_OP_SUB => {
            |slots, dst, lhs, rhs| apply_binary::<T>(BINARY_OP_SUB, slots, dst, lhs, rhs)
        }
        BINARY_OP_MUL => {
            |slots, dst, lhs, rhs| apply_binary::<T>(BINARY_OP_MUL, slots, dst, lhs, rhs)
        }
        BINARY_OP_BIT_AND => {
            |slots, dst, lhs, rhs| apply_binary::<T>(BINARY_OP_BIT_AND, slots, dst, lhs, rhs)
        }
        BINARY_OP_BIT_OR => {
            |slots, dst, lhs, rhs| apply_binary::<T>(BINARY_OP_BIT_OR, slots, dst, lhs, rhs)
        }
        BINARY_OP_BIT_XOR => {
            |slots, dst, lhs, rhs| apply_binary::<T>(BINARY_OP_BIT_XOR, slots, dst, lhs, rhs)
        }
        _ => abort_parallel_runtime(),
    }
}

fn compare_dispatch<T: ParallelCompareOp>(
    op_kind: u8,
) -> fn(&mut [Slot], usize, usize, usize) {
    match op_kind {
        COMPARE_OP_EQ => {
            |slots, dst, lhs, rhs| apply_compare::<T>(COMPARE_OP_EQ, slots, dst, lhs, rhs)
        }
        COMPARE_OP_NE => {
            |slots, dst, lhs, rhs| apply_compare::<T>(COMPARE_OP_NE, slots, dst, lhs, rhs)
        }
        COMPARE_OP_LT => {
            |slots, dst, lhs, rhs| apply_compare::<T>(COMPARE_OP_LT, slots, dst, lhs, rhs)
        }
        COMPARE_OP_LE => {
            |slots, dst, lhs, rhs| apply_compare::<T>(COMPARE_OP_LE, slots, dst, lhs, rhs)
        }
        COMPARE_OP_GT => {
            |slots, dst, lhs, rhs| apply_compare::<T>(COMPARE_OP_GT, slots, dst, lhs, rhs)
        }
        COMPARE_OP_GE => {
            |slots, dst, lhs, rhs| apply_compare::<T>(COMPARE_OP_GE, slots, dst, lhs, rhs)
        }
        _ => abort_parallel_runtime(),
    }
}

// -- Utilities --------------------------------------------------------

fn with_abort_on_panic<R>(f: impl FnOnce() -> R) -> R {
    f()
}

fn abort_parallel_runtime() -> ! {
    process::abort()
}

fn into_handle(group: RuntimeGroup) -> usize {
    Box::into_raw(Box::new(group)) as usize
}

fn group_mut(handle: usize) -> &'static mut RuntimeGroup {
    if handle == 0 {
        abort_parallel_runtime();
    }
    // SAFETY: handle from `into_handle`, used linearly
    unsafe { &mut *ptr::with_exposed_provenance_mut::<RuntimeGroup>(handle) }
}

