#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_group_free")]
#[rustc_nounwind]
pub fn group_free(handle: usize) {
    if runtime_stats_enabled() {
        STATS.group_free_calls.fetch_add(1, Ordering::Relaxed);
    }
    with_abort_on_panic(|| {
        if handle == 0 {
            abort_parallel_runtime();
        }
        let group = group_mut(handle);
        if group.cached {
            group.in_use = false;
            return;
        }
        // SAFETY: handle from `group_new`, freed exactly once
        unsafe {
            drop(Box::from_raw(ptr::with_exposed_provenance_mut::<RuntimeGroup>(handle)));
        }
    });
}

