#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_task_init_outputs4")]
#[rustc_nounwind]
pub fn task_init_outputs4(
    handle: usize,
    task_index: usize,
    slot_count: usize,
    output_count: usize,
    output_slot0: usize,
    output_slot1: usize,
    output_slot2: usize,
    output_slot3: usize,
) {
    if runtime_stats_enabled() {
        STATS.task_init_outputs4_calls.fetch_add(1, Ordering::Relaxed);
    }
    with_abort_on_panic(|| {
        let group = group_mut(handle);
        if group.building_shape {
            let task = group.task_mut(task_index);
            task.init(slot_count, output_count);
            let output_slots = [output_slot0, output_slot1, output_slot2, output_slot3];
            if output_count > output_slots.len() {
                abort_parallel_runtime();
            }
            for (output_index, slot_index) in
                output_slots.into_iter().take(output_count).enumerate()
            {
                task.set_output_slot(output_index, slot_index);
            }
        }
    });
}

