#[rustc_nounwind]
#[inline]
pub fn task_set_input<T: ParallelScalar>(
    handle: usize,
    task_index: usize,
    slot_index: usize,
    value: T,
) {
    let stats_start = maybe_stats_start();
    if runtime_stats_enabled() {
        STATS.task_set_input_calls.fetch_add(1, Ordering::Relaxed);
        STATS.total_input_values_marshaled.fetch_add(1, Ordering::Relaxed);
    }
    let group = group_mut(handle);
    if group.executed {
        if runtime_stats_enabled() {
            STATS.input_updates_while_executed.fetch_add(1, Ordering::Relaxed);
        }
        group.begin_iteration();
    }
    group.task_mut(task_index).set_input(slot_index, value);
    add_elapsed_ns(&STATS.task_set_input_ns, stats_start);
}

