#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_task_push_unary")]
#[rustc_nounwind]
pub fn task_push_unary<T: ParallelUnaryOp>(
    handle: usize,
    task_index: usize,
    dst_slot: usize,
    src_slot: usize,
    op_kind: u8,
) {
    if runtime_stats_enabled() {
        STATS.task_push_unary_calls.fetch_add(1, Ordering::Relaxed);
    }
    with_abort_on_panic(|| {
        let apply = match op_kind {
            UNARY_OP_NOT => apply_unary::<T>,
            UNARY_OP_NEG => apply_unary_neg::<T>,
            _ => abort_parallel_runtime(),
        };
        let group = group_mut(handle);
        if group.building_shape {
            group.task_mut(task_index).push_op(TaskOperation::Unary {
                dst: dst_slot,
                src: src_slot,
                apply,
            });
        }
    });
}

