pub fn group_get_output<T: ParallelScalar>(
    handle: usize,
    task_index: usize,
    output_index: usize,
) -> T {
    let stats_start = maybe_stats_start();
    if runtime_stats_enabled() {
        STATS.get_output_calls.fetch_add(1, Ordering::Relaxed);
        STATS.execute_calls.fetch_add(1, Ordering::Relaxed);
        STATS.total_output_values_read.fetch_add(1, Ordering::Relaxed);
    }
    let group = group_mut(handle);
    group.execute();
    let output = group.task_ref(task_index).get_output(output_index);
    add_elapsed_ns(&STATS.get_output_ns, stats_start);
    maybe_dump_runtime_stats();
    output
}

