#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_group_get_outputs4_raw_ready")]
#[rustc_nounwind]
#[inline]
pub fn group_get_outputs4_raw_ready(
    handle: usize,
    count: usize,
    task0: usize,
    output0: usize,
    task1: usize,
    output1: usize,
    task2: usize,
    output2: usize,
    task3: usize,
    output3: usize,
) -> (usize, usize, usize, usize) {
    let stats_start = maybe_stats_start();
    if runtime_stats_enabled() {
        STATS.get_outputs4_raw_calls.fetch_add(1, Ordering::Relaxed);
        STATS.total_output_values_read.fetch_add(count as u64, Ordering::Relaxed);
    }
    if count == 0 || count > 4 {
        abort_parallel_runtime();
    }

    let group = group_mut(handle);
    let mut outputs = [0usize; 4];
    let descriptors = [
        (task0, output0),
        (task1, output1),
        (task2, output2),
        (task3, output3),
    ];
    for index in 0..count {
        let (task_index, output_index) = descriptors[index];
        outputs[index] = group.task_ref(task_index).get_output_raw(output_index) as usize;
    }
    add_elapsed_ns(&STATS.get_outputs4_raw_ns, stats_start);
    maybe_dump_runtime_stats();
    (outputs[0], outputs[1], outputs[2], outputs[3])
}

