// parallel reduce via chunked partials, dedicated pool

/// Compile-time hard cap on reduce-pool worker threads
const MAX_REDUCE_POOL_THREADS: usize = 32;
/// Compile-time hard cap on chunks per dispatch
const MAX_REDUCE_CHUNKS: usize = MAX_REDUCE_POOL_THREADS + 1;

/// reduce pool size; 0 means serial fallback
fn reduce_pool_size_from_hardware() -> usize {
    if !PARALLEL_RUNTIME_HAS_THREADS {
        return 0;
    }
    if let Ok(s) = env::var("PAR_RUNTIME_THREADS") {
        if let Ok(n) = s.parse::<usize>() {
            return n.clamp(1, MAX_REDUCE_POOL_THREADS);
        }
    }
    let avail = thread::available_parallelism().map(|n| n.get()).unwrap_or(2);
    avail.saturating_sub(1).clamp(1, MAX_REDUCE_POOL_THREADS)
}
/// serial below this; tuned against autovectorized loops
const PARALLEL_REDUCE_THRESHOLD: u64 = 32768;
// Plain `slice.iter().sum()` over primitives is memory-bound
const PARALLEL_REDUCE_THRESHOLD_PLAIN_SUM: u64 = 1 << 20;   // 1,048,576

// op_kind; bit7 slice, bits4-6 type, bits0-3 op
const REDUCE_OP_NONE: u8 = 0;
const REDUCE_OP_ADD: u8 = 1;
const REDUCE_OP_XOR: u8 = 2;
// associative, commutative ops only; saturating excluded
const REDUCE_OP_MUL: u8 = 3;
const REDUCE_OP_AND: u8 = 4;
const REDUCE_OP_OR: u8 = 5;
const REDUCE_OP_MIN: u8 = 6;
const REDUCE_OP_MAX: u8 = 7;
/// count matches; FILTER mode only, add-combined
const REDUCE_OP_COUNT: u8 = 8;
const REDUCE_OP_MASK: u8 = 0x0F;

const REDUCE_TYPE_U64: u8 = 0x00;
const REDUCE_TYPE_U32: u8 = 0x10;
const REDUCE_TYPE_I32: u8 = 0x20;
const REDUCE_TYPE_I64: u8 = 0x30;
const REDUCE_TYPE_USIZE: u8 = 0x40;
const REDUCE_TYPE_ISIZE: u8 = 0x50;
const REDUCE_TYPE_F32: u8 = 0x60;
const REDUCE_TYPE_F64: u8 = 0x70;
const REDUCE_TYPE_MASK: u8 = 0x70;

#[inline]
fn parallel_reduce_serial<F>(start: u64, end: u64, init: u64, op: F, body: fn(u64) -> u64) -> u64
where
    F: Fn(u64, u64) -> u64,
{
    let mut acc = init;
    let mut i = start;
    while i < end {
        acc = op(acc, body(i));
        i = i.wrapping_add(1);
    }
    acc
}

#[repr(align(64))]
struct ReduceWorker {
    /// parker handle, set once at registration
    thread: OnceLock<Thread>,
    /// last epoch acted on, for spin loop
    seen_epoch: AtomicU64,
    /// park state; same protocol as WorkerPool
    park_state: AtomicU32,
    _pad: [u8; 28],
}

impl ReduceWorker {
    const fn new() -> Self {
        Self {
            thread: OnceLock::new(),
            seen_epoch: AtomicU64::new(0),
            park_state: AtomicU32::new(WORKER_STATE_RUNNING),
            _pad: [0; 28],
        }
    }
}

#[repr(align(64))]
struct ReducePool {
    /// dispatch counter; Release covers staging stores
    epoch: AtomicU64,
    /// Single-flight serializer (concurrent reduces are serialised).
    dispatch_in_flight: AtomicBool,
    /// type-erased body fn; valid during dispatch only
    body: AtomicPtr<()>,
    /// Combining op identifier (REDUCE_OP_ADD or REDUCE_OP_XOR).
    op_kind: AtomicU8,
    /// Iteration range for the current dispatch.
    range_start: AtomicU64,
    range_end: AtomicU64,
    /// Total chunks for this dispatch. <= MAX_REDUCE_CHUNKS.
    n_chunks: AtomicUsize,
    /// ticket counter; fetch_add claims a chunk
    next_chunk: AtomicUsize,
    /// finished chunks; dispatcher waits for n_chunks
    completed: AtomicUsize,
    /// per-chunk partials; only first n_chunks read
    results: [AtomicU64; MAX_REDUCE_CHUNKS],
    /// per-element source mode; INDEX, SLICE, RANGE, MAP
    mode: AtomicU8,
    /// slice base in MAP mode; else unused
    slice_ptr: AtomicPtr<()>,
    /// CLOSURE_MAP closure addr; dispatcher stack, caller blocks
    closure_ctx: AtomicUsize,
    /// body panicked; dispatcher re-raises after drain
    dispatch_panicked: AtomicBool,
    /// Element stride in bytes for generic-T modes
    element_stride: AtomicUsize,
    workers: [ReduceWorker; MAX_REDUCE_POOL_THREADS],
    /// Number of worker slots actually spawned
    n_workers: AtomicUsize,
    _pad_tail: [u8; 32],
}

const REDUCE_MODE_INDEX: u8 = 0;
const REDUCE_MODE_SLICE: u8 = 1;
const REDUCE_MODE_RANGE: u8 = 2;
const REDUCE_MODE_MAP: u8 = 3;
/// MAP via trampoline; supports capturing closures
const REDUCE_MODE_CLOSURE_MAP: u8 = 4;
/// filtered slice reduce; predicate gates each element
const REDUCE_MODE_FILTER: u8 = 5;
/// dot product; no fn-ptr, stays vectorizable
const REDUCE_MODE_ZIP_MUL: u8 = 6;
/// General zip + map + reduce
const REDUCE_MODE_ZIP_MAP: u8 = 7;
/// read-only for_each via shared fn-ptr, no partials
const REDUCE_MODE_FOR_EACH: u8 = 8;
/// mutating for_each; disjoint chunks, no aliasing
const REDUCE_MODE_FOR_EACH_MUT: u8 = 9;
/// Side-effect iteration with a capturing closure
const REDUCE_MODE_FOR_EACH_CLOSURE: u8 = 10;
/// range map+collect; slice_ptr is output buffer
const REDUCE_MODE_RANGE_MAP_COLLECT: u8 = 11;
/// Map+collect on a slice source
const REDUCE_MODE_SLICE_MAP_COLLECT: u8 = 12;
/// HashMap for_each via pointer-pair snapshot, 16-byte stride
const REDUCE_MODE_HASHMAP_FOR_EACH: u8 = 13;
/// Generic-T `slice.iter().for_each(body)` over any `T
const REDUCE_MODE_GENERIC_FOR_EACH: u8 = 14;
/// Generic-T `slice.iter().filter(p).count()` for any `T
const REDUCE_MODE_GENERIC_FILTER_COUNT: u8 = 15;

impl ReducePool {
    const fn new() -> Self {
        Self {
            epoch: AtomicU64::new(0),
            dispatch_in_flight: AtomicBool::new(false),
            body: AtomicPtr::new(ptr::null_mut()),
            op_kind: AtomicU8::new(REDUCE_OP_NONE),
            range_start: AtomicU64::new(0),
            range_end: AtomicU64::new(0),
            n_chunks: AtomicUsize::new(0),
            next_chunk: AtomicUsize::new(0),
            completed: AtomicUsize::new(0),
            results: [const { AtomicU64::new(0) }; MAX_REDUCE_CHUNKS],
            mode: AtomicU8::new(REDUCE_MODE_INDEX),
            slice_ptr: AtomicPtr::new(ptr::null_mut()),
            closure_ctx: AtomicUsize::new(0),
            dispatch_panicked: AtomicBool::new(false),
            element_stride: AtomicUsize::new(0),
            workers: [const { ReduceWorker::new() }; MAX_REDUCE_POOL_THREADS],
            n_workers: AtomicUsize::new(0),
            _pad_tail: [0; 32],
        }
    }
}

static REDUCE_POOL_STORAGE: ReducePool = ReducePool::new();
static REDUCE_POOL_INIT: AtomicU8 = AtomicU8::new(0);

fn reduce_pool() -> &'static ReducePool {
    if REDUCE_POOL_INIT.load(Ordering::Acquire) == 2 {
        return &REDUCE_POOL_STORAGE;
    }
    init_reduce_pool()
}

#[cold]
fn init_reduce_pool() -> &'static ReducePool {
    match REDUCE_POOL_INIT.compare_exchange(0, 1, Ordering::AcqRel, Ordering::Acquire) {
        Ok(_) => {
            let target_n = reduce_pool_size_from_hardware();
            // shrink n_workers if spawn fails; avoids hang
            let mut spawned = 0usize;
            for worker_index in 0..target_n {
                match thread::Builder::new()
                    .name(format!("parallel-reduce-worker-{worker_index}"))
                    .spawn(move || reduce_worker_loop(&REDUCE_POOL_STORAGE, worker_index))
                {
                    Ok(_handle) => {
                        spawned += 1;
                    }
                    Err(_e) => break,
                }
            }
            REDUCE_POOL_STORAGE
                .n_workers
                .store(spawned, Ordering::Release);
            // bounded readiness wait; see init_invoke_pool
            let deadline = Instant::now() + Duration::from_secs(5);
            'outer: loop {
                let mut all_ready = true;
                for i in 0..spawned {
                    if REDUCE_POOL_STORAGE.workers[i].thread.get().is_none() {
                        all_ready = false;
                        break;
                    }
                }
                if all_ready {
                    break;
                }
                if Instant::now() >= deadline {
                    for i in 0..spawned {
                        if REDUCE_POOL_STORAGE.workers[i].thread.get().is_none() {
                            REDUCE_POOL_STORAGE
                                .n_workers
                                .store(i, Ordering::Release);
                            break 'outer;
                        }
                    }
                    break;
                }
                hint::spin_loop();
            }
            REDUCE_POOL_INIT.store(2, Ordering::Release);
        }
        Err(_) => {
            while REDUCE_POOL_INIT.load(Ordering::Acquire) != 2 {
                hint::spin_loop();
            }
        }
    }
    &REDUCE_POOL_STORAGE
}

/// compute one chunk; Acquire-reads published staging
#[inline(always)]
fn compute_reduce_chunk(pool: &ReducePool, chunk_idx: usize) -> u64 {
    let body_ptr = pool.body.load(Ordering::Acquire);
    let op_kind = pool.op_kind.load(Ordering::Acquire);
    let start = pool.range_start.load(Ordering::Acquire);
    let end = pool.range_end.load(Ordering::Acquire);
    let n_chunks = pool.n_chunks.load(Ordering::Acquire) as u64;
    let mode = pool.mode.load(Ordering::Acquire);

    // chunk signed types in i64, else underflow
    let type_tag_for_chunk = op_kind & REDUCE_TYPE_MASK;
    let is_signed = matches!(
        type_tag_for_chunk,
        REDUCE_TYPE_I32 | REDUCE_TYPE_I64 | REDUCE_TYPE_ISIZE
    );
    let (my_start, my_end) = if is_signed {
        let start_i = start as i64;
        let end_i = end as i64;
        let total_i = end_i.saturating_sub(start_i).max(0);
        let nc = n_chunks as i64;
        let chunk_size_i = if nc == 0 { 0 } else { total_i / nc };
        let remainder_i = if nc == 0 { 0 } else { total_i % nc };
        let cidx_i = chunk_idx as i64;
        let my_start_i = start_i
            + cidx_i.wrapping_mul(chunk_size_i)
            + cidx_i.min(remainder_i);
        let my_end_i = my_start_i
            + chunk_size_i
            + if cidx_i < remainder_i { 1 } else { 0 };
        (my_start_i as u64, my_end_i as u64)
    } else {
        let total = end.saturating_sub(start);
        let chunk_size = if n_chunks == 0 { 0 } else { total / n_chunks };
        let remainder = if n_chunks == 0 { 0 } else { total % n_chunks };
        let cidx = chunk_idx as u64;
        let my_start = start + cidx * chunk_size + cidx.min(remainder);
        let my_end = my_start + chunk_size + if cidx < remainder { 1 } else { 0 };
        (my_start, my_end)
    };

    // CLOSURE_MAP; trampoline dispatches into capturing closure
    if mode == REDUCE_MODE_CLOSURE_MAP {
        let base_op = op_kind & REDUCE_OP_MASK;
        let type_tag_cmap = op_kind & REDUCE_TYPE_MASK;
        let slice_addr = pool.slice_ptr.load(Ordering::Acquire) as usize;
        let closure_ctx = pool.closure_ctx.load(Ordering::Acquire);
        // SAFETY: caller pinned closure; trampoline ABI matches
        let trampoline_fn: extern "C" fn(usize, usize) -> u64 =
            unsafe { mem::transmute(body_ptr) };
        let map_n = end;
        let map_chunk_size = if n_chunks == 0 { 0 } else { map_n / n_chunks };
        let map_remainder = if n_chunks == 0 { 0 } else { map_n % n_chunks };
        let cidx = chunk_idx as u64;
        let map_start = cidx * map_chunk_size + cidx.min(map_remainder);
        let map_end = map_start + map_chunk_size + if cidx < map_remainder { 1 } else { 0 };

        // trampoline widens to u64; narrow back, accumulate
        macro_rules! cmap_typed {
            ($T:ty) => {{
                let slice_ptr = crate::ptr::with_exposed_provenance::<$T>(slice_addr);
                let mut typed_acc: $T = match base_op {
                    REDUCE_OP_MUL => 1 as $T,
                    _ => 0 as $T,
                };
                let mut i = map_start as usize;
                let stop = map_end as usize;
                while i < stop {
                    // SAFETY: chunking keeps i < n
                    let item_ptr = unsafe { slice_ptr.add(i) };
                    let item_addr = (item_ptr as *const $T).expose_provenance();
                    let v_u64 = trampoline_fn(closure_ctx, item_addr);
                    let v: $T = v_u64 as $T;
                    typed_acc = match base_op {
                        REDUCE_OP_ADD => typed_acc.wrapping_add(v),
                        REDUCE_OP_MUL => typed_acc.wrapping_mul(v),
                        _ => typed_acc,
                    };
                    i = i.wrapping_add(1);
                }
                typed_acc as u64
            }};
        }
        return match type_tag_cmap {
            REDUCE_TYPE_U64 => cmap_typed!(u64),
            REDUCE_TYPE_U32 => cmap_typed!(u32),
            REDUCE_TYPE_I64 => cmap_typed!(i64),
            REDUCE_TYPE_I32 => cmap_typed!(i32),
            _ => 0,
        };
    }

    // MAP mode; body(&x) per element, same-type only
    if mode == REDUCE_MODE_MAP {
        let base_op = op_kind & REDUCE_OP_MASK;
        let type_tag_map = op_kind & REDUCE_TYPE_MASK;
        let slice_addr = pool.slice_ptr.load(Ordering::Acquire) as usize;
        // map mode; re-derive chunk bounds from length
        let map_n = end;
        let map_total = map_n;
        let map_chunk_size = if n_chunks == 0 { 0 } else { map_total / n_chunks };
        let map_remainder = if n_chunks == 0 { 0 } else { map_total % n_chunks };
        let cidx = chunk_idx as u64;
        let map_start = cidx * map_chunk_size + cidx.min(map_remainder);
        let map_end = map_start + map_chunk_size + if cidx < map_remainder { 1 } else { 0 };
        macro_rules! map_typed {
            ($T:ty) => {{
                let slice_ptr: *const $T =
                    crate::ptr::with_exposed_provenance::<$T>(slice_addr);
                let body: fn(&$T) -> $T = unsafe {
                    crate::mem::transmute::<*mut (), fn(&$T) -> $T>(body_ptr)
                };
                let mut typed_acc: $T = match base_op {
                    REDUCE_OP_ADD | REDUCE_OP_XOR | REDUCE_OP_OR => 0 as $T,
                    REDUCE_OP_MUL => 1 as $T,
                    REDUCE_OP_AND => !(0 as $T),
                    REDUCE_OP_MIN => <$T>::MAX,
                    REDUCE_OP_MAX => <$T>::MIN,
                    _ => 0 as $T,
                };
                let mut i = map_start as usize;
                let stop = map_end as usize;
                match base_op {
                    REDUCE_OP_ADD => while i < stop {
                        let v_ref: &$T = unsafe { &*slice_ptr.add(i) };
                        typed_acc = typed_acc.wrapping_add(body(v_ref));
                        i = i.wrapping_add(1);
                    },
                    REDUCE_OP_XOR => while i < stop {
                        let v_ref: &$T = unsafe { &*slice_ptr.add(i) };
                        typed_acc ^= body(v_ref);
                        i = i.wrapping_add(1);
                    },
                    REDUCE_OP_MUL => while i < stop {
                        let v_ref: &$T = unsafe { &*slice_ptr.add(i) };
                        typed_acc = typed_acc.wrapping_mul(body(v_ref));
                        i = i.wrapping_add(1);
                    },
                    _ => {}
                }
                typed_acc as u64
            }};
        }
        return match type_tag_map {
            REDUCE_TYPE_U64 => map_typed!(u64),
            REDUCE_TYPE_U32 => map_typed!(u32),
            REDUCE_TYPE_I32 => map_typed!(i32),
            REDUCE_TYPE_I64 => map_typed!(i64),
            REDUCE_TYPE_USIZE => map_typed!(usize),
            REDUCE_TYPE_ISIZE => map_typed!(isize),
            _ => 0,
        };
    }

    // RANGE mode; value is the index itself
    if mode == REDUCE_MODE_RANGE {
        let base_op = op_kind & REDUCE_OP_MASK;
        let type_tag_range = op_kind & REDUCE_TYPE_MASK;
        macro_rules! range_typed {
            ($T:ty) => {{
                let mut typed_acc: $T = match base_op {
                    REDUCE_OP_ADD | REDUCE_OP_XOR | REDUCE_OP_OR => 0 as $T,
                    REDUCE_OP_MUL => 1 as $T,
                    REDUCE_OP_AND => !(0 as $T),
                    REDUCE_OP_MIN => <$T>::MAX,
                    REDUCE_OP_MAX => <$T>::MIN,
                    _ => 0 as $T,
                };
                let mut i: $T = my_start as $T;
                let stop: $T = my_end as $T;
                match base_op {
                    REDUCE_OP_ADD => while i < stop {
                        typed_acc = typed_acc.wrapping_add(i);
                        i = i.wrapping_add(1 as $T);
                    },
                    REDUCE_OP_XOR => while i < stop {
                        typed_acc ^= i;
                        i = i.wrapping_add(1 as $T);
                    },
                    REDUCE_OP_MUL => while i < stop {
                        typed_acc = typed_acc.wrapping_mul(i);
                        i = i.wrapping_add(1 as $T);
                    },
                    REDUCE_OP_AND => while i < stop {
                        typed_acc &= i;
                        i = i.wrapping_add(1 as $T);
                    },
                    REDUCE_OP_OR => while i < stop {
                        typed_acc |= i;
                        i = i.wrapping_add(1 as $T);
                    },
                    REDUCE_OP_MIN => while i < stop {
                        if i < typed_acc { typed_acc = i; }
                        i = i.wrapping_add(1 as $T);
                    },
                    REDUCE_OP_MAX => while i < stop {
                        if i > typed_acc { typed_acc = i; }
                        i = i.wrapping_add(1 as $T);
                    },
                    _ => {}
                }
                typed_acc as u64
            }};
        }
        return match type_tag_range {
            REDUCE_TYPE_U64 => range_typed!(u64),
            REDUCE_TYPE_U32 => range_typed!(u32),
            REDUCE_TYPE_I32 => range_typed!(i32),
            REDUCE_TYPE_I64 => range_typed!(i64),
            REDUCE_TYPE_USIZE => range_typed!(usize),
            REDUCE_TYPE_ISIZE => range_typed!(isize),
            _ => 0,
        };
    }

    // filter dispatch; accumulate only where predicate holds
    if mode == REDUCE_MODE_FILTER {
        let base_op = op_kind & REDUCE_OP_MASK;
        let type_tag_filt = op_kind & REDUCE_TYPE_MASK;
        let slice_addr = pool.slice_ptr.load(Ordering::Acquire) as usize;
        // body_ptr already has provenance
        let map_n = end;
        let map_chunk_size = if n_chunks == 0 { 0 } else { map_n / n_chunks };
        let map_remainder = if n_chunks == 0 { 0 } else { map_n % n_chunks };
        let cidx = chunk_idx as u64;
        let map_start = cidx * map_chunk_size + cidx.min(map_remainder);
        let map_end =
            map_start + map_chunk_size + if cidx < map_remainder { 1 } else { 0 };
        macro_rules! filter_typed {
            ($T:ty) => {{
                // SAFETY: slice pinned; pred_addr from real fn
                let slice_ptr = crate::ptr::with_exposed_provenance::<$T>(slice_addr);
                // Predicate signature mirrors `Iterator::filter`'s `F
                let pred: fn(&&$T) -> bool = unsafe {
                    crate::mem::transmute::<*mut (), fn(&&$T) -> bool>(body_ptr)
                };
                let mut typed_acc: $T = match base_op {
                    REDUCE_OP_MUL => 1 as $T,
                    _ => 0 as $T,
                };
                let mut i = map_start as usize;
                let stop = map_end as usize;
                while i < stop {
                    // SAFETY: chunking keeps i < n
                    let v_ref: &$T = unsafe { &*slice_ptr.add(i) };
                    if pred(&v_ref) {
                        let v = *v_ref;
                        typed_acc = match base_op {
                            REDUCE_OP_ADD => typed_acc.wrapping_add(v),
                            REDUCE_OP_MUL => typed_acc.wrapping_mul(v),
                            REDUCE_OP_COUNT => typed_acc.wrapping_add(1 as $T),
                            _ => typed_acc,
                        };
                    }
                    i = i.wrapping_add(1);
                }
                typed_acc as u64
            }};
        }
        return match type_tag_filt {
            REDUCE_TYPE_U64 => filter_typed!(u64),
            REDUCE_TYPE_U32 => filter_typed!(u32),
            REDUCE_TYPE_I64 => filter_typed!(i64),
            REDUCE_TYPE_I32 => filter_typed!(i32),
            _ => 0,
        };
    }

    // dot product; no fn-ptr so LLVM vectorizes
    if mode == REDUCE_MODE_ZIP_MUL {
        let slice_a_addr = pool.slice_ptr.load(Ordering::Acquire) as usize;
        let slice_b_addr = body_ptr as usize;
        let type_tag_zm = op_kind & REDUCE_TYPE_MASK;
        let map_n = end;
        let map_chunk_size = if n_chunks == 0 { 0 } else { map_n / n_chunks };
        let map_remainder = if n_chunks == 0 { 0 } else { map_n % n_chunks };
        let cidx = chunk_idx as u64;
        let map_start = cidx * map_chunk_size + cidx.min(map_remainder);
        let map_end =
            map_start + map_chunk_size + if cidx < map_remainder { 1 } else { 0 };
        macro_rules! zip_mul_typed {
            ($T:ty) => {{
                let a_ptr = crate::ptr::with_exposed_provenance::<$T>(slice_a_addr);
                let b_ptr = crate::ptr::with_exposed_provenance::<$T>(slice_b_addr);
                let mut typed_acc: $T = 0 as $T;
                let mut i = map_start as usize;
                let stop = map_end as usize;
                // Tight loop, no branch / no fn-ptr
                while i < stop {
                    // SAFETY: chunked indexing; both slices pinned
                    let av = unsafe { *a_ptr.add(i) };
                    let bv = unsafe { *b_ptr.add(i) };
                    typed_acc = typed_acc.wrapping_add(av.wrapping_mul(bv));
                    i = i.wrapping_add(1);
                }
                typed_acc as u64
            }};
        }
        // float path; ship partial as `to_bits()`
        macro_rules! zip_mul_typed_float {
            ($T:ty, $to_u64:expr) => {{
                let a_ptr = crate::ptr::with_exposed_provenance::<$T>(slice_a_addr);
                let b_ptr = crate::ptr::with_exposed_provenance::<$T>(slice_b_addr);
                let mut typed_acc: $T = 0.0 as $T;
                let mut i = map_start as usize;
                let stop = map_end as usize;
                while i < stop {
                    // SAFETY: same as integer arm.
                    let av = unsafe { *a_ptr.add(i) };
                    let bv = unsafe { *b_ptr.add(i) };
                    typed_acc = typed_acc + av * bv;
                    i = i.wrapping_add(1);
                }
                $to_u64(typed_acc)
            }};
        }
        return match type_tag_zm {
            REDUCE_TYPE_U64 => zip_mul_typed!(u64),
            REDUCE_TYPE_U32 => zip_mul_typed!(u32),
            REDUCE_TYPE_I64 => zip_mul_typed!(i64),
            REDUCE_TYPE_I32 => zip_mul_typed!(i32),
            REDUCE_TYPE_F64 => zip_mul_typed_float!(f64, |x: f64| x.to_bits()),
            REDUCE_TYPE_F32 => zip_mul_typed_float!(f32, |x: f32| x.to_bits() as u64),
            _ => 0,
        };
    }

    // general zip-map; accumulate combiner(a[i], b[i])
    if mode == REDUCE_MODE_ZIP_MAP {
        let base_op = op_kind & REDUCE_OP_MASK;
        let type_tag_zm = op_kind & REDUCE_TYPE_MASK;
        let slice_a_addr = pool.slice_ptr.load(Ordering::Acquire) as usize;
        let slice_b_addr = pool.closure_ctx.load(Ordering::Acquire);
        // body_ptr is the combiner
        let map_n = end;
        let map_chunk_size = if n_chunks == 0 { 0 } else { map_n / n_chunks };
        let map_remainder = if n_chunks == 0 { 0 } else { map_n % n_chunks };
        let cidx = chunk_idx as u64;
        let map_start = cidx * map_chunk_size + cidx.min(map_remainder);
        let map_end =
            map_start + map_chunk_size + if cidx < map_remainder { 1 } else { 0 };
        macro_rules! zip_map_typed {
            ($T:ty) => {{
                let a_ptr = crate::ptr::with_exposed_provenance::<$T>(slice_a_addr);
                let b_ptr = crate::ptr::with_exposed_provenance::<$T>(slice_b_addr);
                // Combiner takes a tuple `(&T, &T)`
                let combiner: fn((&$T, &$T)) -> $T = unsafe {
                    crate::mem::transmute::<*mut (), fn((&$T, &$T)) -> $T>(body_ptr)
                };
                let mut typed_acc: $T = match base_op {
                    REDUCE_OP_MUL => 1 as $T,
                    _ => 0 as $T,
                };
                let mut i = map_start as usize;
                let stop = map_end as usize;
                while i < stop {
                    // SAFETY: chunked indexing; both slices pinned
                    let av: &$T = unsafe { &*a_ptr.add(i) };
                    let bv: &$T = unsafe { &*b_ptr.add(i) };
                    let v = combiner((av, bv));
                    typed_acc = match base_op {
                        REDUCE_OP_ADD => typed_acc.wrapping_add(v),
                        REDUCE_OP_MUL => typed_acc.wrapping_mul(v),
                        _ => typed_acc,
                    };
                    i = i.wrapping_add(1);
                }
                typed_acc as u64
            }};
        }
        // Float specialization for general zip-map
        macro_rules! zip_map_typed_float {
            ($T:ty, $to_u64:expr) => {{
                let a_ptr = crate::ptr::with_exposed_provenance::<$T>(slice_a_addr);
                let b_ptr = crate::ptr::with_exposed_provenance::<$T>(slice_b_addr);
                let combiner: fn((&$T, &$T)) -> $T = unsafe {
                    crate::mem::transmute::<*mut (), fn((&$T, &$T)) -> $T>(body_ptr)
                };
                let mut typed_acc: $T = match base_op {
                    REDUCE_OP_MUL => 1.0 as $T,
                    _ => 0.0 as $T,
                };
                let mut i = map_start as usize;
                let stop = map_end as usize;
                while i < stop {
                    let av: &$T = unsafe { &*a_ptr.add(i) };
                    let bv: &$T = unsafe { &*b_ptr.add(i) };
                    let v = combiner((av, bv));
                    typed_acc = match base_op {
                        REDUCE_OP_ADD => typed_acc + v,
                        REDUCE_OP_MUL => typed_acc * v,
                        _ => typed_acc,
                    };
                    i = i.wrapping_add(1);
                }
                $to_u64(typed_acc)
            }};
        }
        return match type_tag_zm {
            REDUCE_TYPE_U64 => zip_map_typed!(u64),
            REDUCE_TYPE_U32 => zip_map_typed!(u32),
            REDUCE_TYPE_I64 => zip_map_typed!(i64),
            REDUCE_TYPE_I32 => zip_map_typed!(i32),
            REDUCE_TYPE_F64 => zip_map_typed_float!(f64, |x: f64| x.to_bits()),
            REDUCE_TYPE_F32 => zip_map_typed_float!(f32, |x: f32| x.to_bits() as u64),
            _ => 0,
        };
    }

    // read-only for_each; shared fn-ptr, no partials
    if mode == REDUCE_MODE_FOR_EACH {
        let type_tag = op_kind & REDUCE_TYPE_MASK;
        let slice_addr = pool.slice_ptr.load(Ordering::Acquire) as usize;
        let map_n = end;
        let map_chunk_size = if n_chunks == 0 { 0 } else { map_n / n_chunks };
        let map_remainder = if n_chunks == 0 { 0 } else { map_n % n_chunks };
        let cidx = chunk_idx as u64;
        let map_start = cidx * map_chunk_size + cidx.min(map_remainder);
        let map_end =
            map_start + map_chunk_size + if cidx < map_remainder { 1 } else { 0 };
        macro_rules! foreach_typed {
            ($T:ty) => {{
                let slice_ptr = crate::ptr::with_exposed_provenance::<$T>(slice_addr);
                let body: fn(&$T) = unsafe {
                    crate::mem::transmute::<*mut (), fn(&$T)>(body_ptr)
                };
                let mut i = map_start as usize;
                let stop = map_end as usize;
                while i < stop {
                    // SAFETY: chunked indexing; caller pinned slice
                    let v_ref: &$T = unsafe { &*slice_ptr.add(i) };
                    body(v_ref);
                    i = i.wrapping_add(1);
                }
                0u64
            }};
        }
        return match type_tag {
            REDUCE_TYPE_U64 => foreach_typed!(u64),
            REDUCE_TYPE_U32 => foreach_typed!(u32),
            REDUCE_TYPE_I64 => foreach_typed!(i64),
            REDUCE_TYPE_I32 => foreach_typed!(i32),
            REDUCE_TYPE_USIZE => foreach_typed!(usize),
            REDUCE_TYPE_ISIZE => foreach_typed!(isize),
            _ => 0,
        };
    }

    // mutating for_each; disjoint chunks, no aliasing
    if mode == REDUCE_MODE_FOR_EACH_MUT {
        let type_tag = op_kind & REDUCE_TYPE_MASK;
        let slice_addr = pool.slice_ptr.load(Ordering::Acquire) as usize;
        let map_n = end;
        let map_chunk_size = if n_chunks == 0 { 0 } else { map_n / n_chunks };
        let map_remainder = if n_chunks == 0 { 0 } else { map_n % n_chunks };
        let cidx = chunk_idx as u64;
        let map_start = cidx * map_chunk_size + cidx.min(map_remainder);
        let map_end =
            map_start + map_chunk_size + if cidx < map_remainder { 1 } else { 0 };
        macro_rules! foreach_mut_typed {
            ($T:ty) => {{
                let slice_ptr = crate::ptr::with_exposed_provenance_mut::<$T>(slice_addr);
                let body: fn(&mut $T) = unsafe {
                    crate::mem::transmute::<*mut (), fn(&mut $T)>(body_ptr)
                };
                let mut i = map_start as usize;
                let stop = map_end as usize;
                while i < stop {
                    // SAFETY: disjoint chunks, no shared &mut
                    let v_ref: &mut $T = unsafe { &mut *slice_ptr.add(i) };
                    body(v_ref);
                    i = i.wrapping_add(1);
                }
                0u64
            }};
        }
        return match type_tag {
            REDUCE_TYPE_U64 => foreach_mut_typed!(u64),
            REDUCE_TYPE_U32 => foreach_mut_typed!(u32),
            REDUCE_TYPE_I64 => foreach_mut_typed!(i64),
            REDUCE_TYPE_I32 => foreach_mut_typed!(i32),
            REDUCE_TYPE_USIZE => foreach_mut_typed!(usize),
            REDUCE_TYPE_ISIZE => foreach_mut_typed!(isize),
            _ => 0,
        };
    }

    // for_each via dyn Fn trampoline; closure_ctx pinned
    if mode == REDUCE_MODE_FOR_EACH_CLOSURE {
        let type_tag = op_kind & REDUCE_TYPE_MASK;
        let slice_addr = pool.slice_ptr.load(Ordering::Acquire) as usize;
        let closure_ctx = pool.closure_ctx.load(Ordering::Acquire);
        let trampoline_fn: extern "C" fn(usize, usize) = unsafe {
            mem::transmute(body_ptr)
        };
        let map_n = end;
        let map_chunk_size = if n_chunks == 0 { 0 } else { map_n / n_chunks };
        let map_remainder = if n_chunks == 0 { 0 } else { map_n % n_chunks };
        let cidx = chunk_idx as u64;
        let map_start = cidx * map_chunk_size + cidx.min(map_remainder);
        let map_end =
            map_start + map_chunk_size + if cidx < map_remainder { 1 } else { 0 };
        macro_rules! foreach_closure_typed {
            ($T:ty) => {{
                let slice_ptr = crate::ptr::with_exposed_provenance::<$T>(slice_addr);
                let mut i = map_start as usize;
                let stop = map_end as usize;
                while i < stop {
                    let item_ptr = unsafe { slice_ptr.add(i) };
                    let item_addr = (item_ptr as *const $T).expose_provenance();
                    trampoline_fn(closure_ctx, item_addr);
                    i = i.wrapping_add(1);
                }
                0u64
            }};
        }
        return match type_tag {
            REDUCE_TYPE_U64 => foreach_closure_typed!(u64),
            REDUCE_TYPE_U32 => foreach_closure_typed!(u32),
            REDUCE_TYPE_I64 => foreach_closure_typed!(i64),
            REDUCE_TYPE_I32 => foreach_closure_typed!(i32),
            _ => 0,
        };
    }

    // range map+collect; disjoint writes into output buffer
    if mode == REDUCE_MODE_RANGE_MAP_COLLECT {
        let type_tag = op_kind & REDUCE_TYPE_MASK;
        let out_addr = pool.slice_ptr.load(Ordering::Acquire) as usize;
        let map_n = end;
        let map_chunk_size = if n_chunks == 0 { 0 } else { map_n / n_chunks };
        let map_remainder = if n_chunks == 0 { 0 } else { map_n % n_chunks };
        let cidx = chunk_idx as u64;
        let map_start = cidx * map_chunk_size + cidx.min(map_remainder);
        let map_end =
            map_start + map_chunk_size + if cidx < map_remainder { 1 } else { 0 };
        macro_rules! collect_range_typed {
            ($T:ty) => {{
                let out_ptr = crate::ptr::with_exposed_provenance_mut::<$T>(out_addr);
                let body: fn(u64) -> $T = unsafe {
                    crate::mem::transmute::<*mut (), fn(u64) -> $T>(body_ptr)
                };
                let mut i = map_start;
                while i < map_end {
                    let v = body(i);
                    // SAFETY: out holds `end` slots; chunks disjoint
                    unsafe { core::ptr::write(out_ptr.add(i as usize), v) };
                    i = i.wrapping_add(1);
                }
                0u64
            }};
        }
        return match type_tag {
            REDUCE_TYPE_U64 => collect_range_typed!(u64),
            REDUCE_TYPE_U32 => collect_range_typed!(u32),
            REDUCE_TYPE_I64 => collect_range_typed!(i64),
            REDUCE_TYPE_I32 => collect_range_typed!(i32),
            REDUCE_TYPE_USIZE => collect_range_typed!(usize),
            REDUCE_TYPE_ISIZE => collect_range_typed!(isize),
            _ => 0,
        };
    }

    // slice map+collect; same-type only for now
    if mode == REDUCE_MODE_SLICE_MAP_COLLECT {
        let type_tag = op_kind & REDUCE_TYPE_MASK;
        let out_addr = pool.slice_ptr.load(Ordering::Acquire) as usize;
        let in_addr = pool.closure_ctx.load(Ordering::Acquire);
        let map_n = end;
        let map_chunk_size = if n_chunks == 0 { 0 } else { map_n / n_chunks };
        let map_remainder = if n_chunks == 0 { 0 } else { map_n % n_chunks };
        let cidx = chunk_idx as u64;
        let map_start = cidx * map_chunk_size + cidx.min(map_remainder);
        let map_end =
            map_start + map_chunk_size + if cidx < map_remainder { 1 } else { 0 };
        macro_rules! collect_slice_typed {
            ($T:ty) => {{
                let out_ptr = crate::ptr::with_exposed_provenance_mut::<$T>(out_addr);
                let in_ptr = crate::ptr::with_exposed_provenance::<$T>(in_addr);
                let body: fn(&$T) -> $T = unsafe {
                    crate::mem::transmute::<*mut (), fn(&$T) -> $T>(body_ptr)
                };
                let mut i = map_start as usize;
                let stop = map_end as usize;
                while i < stop {
                    let in_ref: &$T = unsafe { &*in_ptr.add(i) };
                    let v = body(in_ref);
                    unsafe { core::ptr::write(out_ptr.add(i), v) };
                    i = i.wrapping_add(1);
                }
                0u64
            }};
        }
        return match type_tag {
            REDUCE_TYPE_U64 => collect_slice_typed!(u64),
            REDUCE_TYPE_U32 => collect_slice_typed!(u32),
            REDUCE_TYPE_I64 => collect_slice_typed!(i64),
            REDUCE_TYPE_I32 => collect_slice_typed!(i32),
            REDUCE_TYPE_USIZE => collect_slice_typed!(usize),
            REDUCE_TYPE_ISIZE => collect_slice_typed!(isize),
            _ => 0,
        };
    }

    // HashMap for_each over snapshot; trampoline reads pairs
    if mode == REDUCE_MODE_HASHMAP_FOR_EACH {
        let snap_addr = pool.slice_ptr.load(Ordering::Acquire) as usize;
        let closure_ctx = pool.closure_ctx.load(Ordering::Acquire);
        // Trampoline takes (closure_ctx, pair_addr).
        let trampoline_fn: extern "C" fn(usize, usize) = unsafe {
            mem::transmute(body_ptr)
        };
        let map_n = end;
        let map_chunk_size = if n_chunks == 0 { 0 } else { map_n / n_chunks };
        let map_remainder = if n_chunks == 0 { 0 } else { map_n % n_chunks };
        let cidx = chunk_idx as u64;
        let map_start = cidx * map_chunk_size + cidx.min(map_remainder);
        let map_end =
            map_start + map_chunk_size + if cidx < map_remainder { 1 } else { 0 };
        let mut i = map_start as usize;
        let stop = map_end as usize;
        // pair is 16 bytes on 64-bit
        let stride = core::mem::size_of::<(usize, usize)>();
        while i < stop {
            let pair_addr = snap_addr + i * stride;
            trampoline_fn(closure_ctx, pair_addr);
            i = i.wrapping_add(1);
        }
        return 0;
    }

    // generic for_each, stride-driven via trampoline
    if mode == REDUCE_MODE_GENERIC_FOR_EACH {
        let slice_addr = pool.slice_ptr.load(Ordering::Acquire) as usize;
        let closure_ctx = pool.closure_ctx.load(Ordering::Acquire);
        let stride = pool.element_stride.load(Ordering::Acquire);
        let trampoline_fn: extern "C" fn(usize, usize) = unsafe {
            mem::transmute(body_ptr)
        };
        let map_n = end;
        let map_chunk_size = if n_chunks == 0 { 0 } else { map_n / n_chunks };
        let map_remainder = if n_chunks == 0 { 0 } else { map_n % n_chunks };
        let cidx = chunk_idx as u64;
        let map_start = cidx * map_chunk_size + cidx.min(map_remainder);
        let map_end =
            map_start + map_chunk_size + if cidx < map_remainder { 1 } else { 0 };
        let mut i = map_start as usize;
        let stop = map_end as usize;
        while i < stop {
            let item_addr = slice_addr + i * stride;
            trampoline_fn(closure_ctx, item_addr);
            i = i.wrapping_add(1);
        }
        return 0;
    }

    // generic filter+count; trampoline returns 0/1, summed
    if mode == REDUCE_MODE_GENERIC_FILTER_COUNT {
        let slice_addr = pool.slice_ptr.load(Ordering::Acquire) as usize;
        let closure_ctx = pool.closure_ctx.load(Ordering::Acquire);
        let stride = pool.element_stride.load(Ordering::Acquire);
        let trampoline_fn: extern "C" fn(usize, usize) -> u64 = unsafe {
            mem::transmute(body_ptr)
        };
        let map_n = end;
        let map_chunk_size = if n_chunks == 0 { 0 } else { map_n / n_chunks };
        let map_remainder = if n_chunks == 0 { 0 } else { map_n % n_chunks };
        let cidx = chunk_idx as u64;
        let map_start = cidx * map_chunk_size + cidx.min(map_remainder);
        let map_end =
            map_start + map_chunk_size + if cidx < map_remainder { 1 } else { 0 };
        let mut acc = 0u64;
        let mut i = map_start as usize;
        let stop = map_end as usize;
        while i < stop {
            let item_addr = slice_addr + i * stride;
            acc = acc.wrapping_add(trampoline_fn(closure_ctx, item_addr));
            i = i.wrapping_add(1);
        }
        return acc;
    }

    // Slice-mode op-kinds carry the REDUCE_OP_SLICE_BIT
    if (op_kind & REDUCE_OP_SLICE_BIT) != 0 {
        let base_op = op_kind & REDUCE_OP_MASK;
        let type_tag_slice = op_kind & REDUCE_TYPE_MASK;
        macro_rules! slice_typed {
            ($T:ty) => {{
                // SAFETY: caller keeps slice alive; indices in-range
                let slice_ptr = body_ptr as *const $T;
                let mut typed_acc: $T = match base_op {
                    REDUCE_OP_ADD | REDUCE_OP_XOR | REDUCE_OP_OR => 0 as $T,
                    REDUCE_OP_MUL => 1 as $T,
                    REDUCE_OP_AND => !(0 as $T),
                    REDUCE_OP_MIN => <$T>::MAX,
                    REDUCE_OP_MAX => <$T>::MIN,
                    _ => 0 as $T,
                };
                let mut i = my_start as usize;
                let stop = my_end as usize;
                match base_op {
                    REDUCE_OP_ADD => while i < stop {
                        let v = unsafe { *slice_ptr.add(i) };
                        typed_acc = typed_acc.wrapping_add(v);
                        i = i.wrapping_add(1);
                    },
                    REDUCE_OP_XOR => while i < stop {
                        let v = unsafe { *slice_ptr.add(i) };
                        typed_acc ^= v;
                        i = i.wrapping_add(1);
                    },
                    REDUCE_OP_MUL => while i < stop {
                        let v = unsafe { *slice_ptr.add(i) };
                        typed_acc = typed_acc.wrapping_mul(v);
                        i = i.wrapping_add(1);
                    },
                    REDUCE_OP_AND => while i < stop {
                        let v = unsafe { *slice_ptr.add(i) };
                        typed_acc &= v;
                        i = i.wrapping_add(1);
                    },
                    REDUCE_OP_OR => while i < stop {
                        let v = unsafe { *slice_ptr.add(i) };
                        typed_acc |= v;
                        i = i.wrapping_add(1);
                    },
                    REDUCE_OP_MIN => while i < stop {
                        let v = unsafe { *slice_ptr.add(i) };
                        if v < typed_acc { typed_acc = v; }
                        i = i.wrapping_add(1);
                    },
                    REDUCE_OP_MAX => while i < stop {
                        let v = unsafe { *slice_ptr.add(i) };
                        if v > typed_acc { typed_acc = v; }
                        i = i.wrapping_add(1);
                    },
                    _ => {}
                }
                typed_acc as u64
            }};
        }
        // floats use +/* and `to_bits()`; opt-in only
        macro_rules! slice_typed_float {
            ($T:ty) => {{
                let slice_ptr = body_ptr as *const $T;
                let mut typed_acc: $T = match base_op {
                    REDUCE_OP_MUL => 1.0 as $T,
                    REDUCE_OP_MIN => <$T>::INFINITY,
                    REDUCE_OP_MAX => <$T>::NEG_INFINITY,
                    _ => 0.0 as $T,
                };
                let mut i = my_start as usize;
                let stop = my_end as usize;
                match base_op {
                    REDUCE_OP_ADD => while i < stop {
                        let v = unsafe { *slice_ptr.add(i) };
                        typed_acc = typed_acc + v;
                        i = i.wrapping_add(1);
                    },
                    REDUCE_OP_MUL => while i < stop {
                        let v = unsafe { *slice_ptr.add(i) };
                        typed_acc = typed_acc * v;
                        i = i.wrapping_add(1);
                    },
                    REDUCE_OP_MIN => while i < stop {
                        let v = unsafe { *slice_ptr.add(i) };
                        if v < typed_acc { typed_acc = v; }
                        i = i.wrapping_add(1);
                    },
                    REDUCE_OP_MAX => while i < stop {
                        let v = unsafe { *slice_ptr.add(i) };
                        if v > typed_acc { typed_acc = v; }
                        i = i.wrapping_add(1);
                    },
                    _ => {}
                }
                typed_acc.to_bits() as u64
            }};
        }
        return match type_tag_slice {
            REDUCE_TYPE_U64 => slice_typed!(u64),
            REDUCE_TYPE_U32 => slice_typed!(u32),
            REDUCE_TYPE_I32 => slice_typed!(i32),
            REDUCE_TYPE_I64 => slice_typed!(i64),
            REDUCE_TYPE_USIZE => slice_typed!(usize),
            REDUCE_TYPE_ISIZE => slice_typed!(isize),
            REDUCE_TYPE_F32 => slice_typed_float!(f32),
            REDUCE_TYPE_F64 => slice_typed_float!(f64),
            _ => 0,
        };
    }

    // INDEX mode; body type from type tag
    let type_tag = op_kind & REDUCE_TYPE_MASK;
    let base_op = op_kind & REDUCE_OP_MASK;

    macro_rules! reduce_typed {
        ($T:ty) => {{
            // SAFETY: body_ptr holds a valid typed fn
            let body: fn($T) -> $T = unsafe {
                crate::mem::transmute::<*mut (), fn($T) -> $T>(body_ptr)
            };
            // per-op identity for typed accumulator
            let mut typed_acc: $T = match base_op {
                REDUCE_OP_ADD | REDUCE_OP_XOR | REDUCE_OP_OR => 0 as $T,
                REDUCE_OP_MUL => 1 as $T,
                REDUCE_OP_AND => !(0 as $T),       // all-ones bit pattern
                REDUCE_OP_MIN => <$T>::MAX,
                REDUCE_OP_MAX => <$T>::MIN,
                _ => 0 as $T,
            };
            // count in $T; unsigned compare breaks signed
            let mut i: $T = my_start as $T;
            let stop: $T = my_end as $T;
            match base_op {
                REDUCE_OP_ADD => {
                    while i < stop {
                        typed_acc = typed_acc.wrapping_add(body(i));
                        i = i.wrapping_add(1 as $T);
                    }
                }
                REDUCE_OP_XOR => {
                    while i < stop {
                        typed_acc ^= body(i);
                        i = i.wrapping_add(1 as $T);
                    }
                }
                REDUCE_OP_MUL => {
                    while i < stop {
                        typed_acc = typed_acc.wrapping_mul(body(i));
                        i = i.wrapping_add(1 as $T);
                    }
                }
                REDUCE_OP_AND => {
                    while i < stop {
                        typed_acc &= body(i);
                        i = i.wrapping_add(1 as $T);
                    }
                }
                REDUCE_OP_OR => {
                    while i < stop {
                        typed_acc |= body(i);
                        i = i.wrapping_add(1 as $T);
                    }
                }
                REDUCE_OP_MIN => {
                    while i < stop {
                        let v = body(i);
                        if v < typed_acc { typed_acc = v; }
                        i = i.wrapping_add(1 as $T);
                    }
                }
                REDUCE_OP_MAX => {
                    while i < stop {
                        let v = body(i);
                        if v > typed_acc { typed_acc = v; }
                        i = i.wrapping_add(1 as $T);
                    }
                }
                _ => {}
            }
            // Round-trip the typed accumulator through u64 storage
            typed_acc as u64
        }};
    }

    let acc = match type_tag {
        REDUCE_TYPE_U64 => reduce_typed!(u64),
        REDUCE_TYPE_U32 => reduce_typed!(u32),
        REDUCE_TYPE_I32 => reduce_typed!(i32),
        REDUCE_TYPE_I64 => reduce_typed!(i64),
        REDUCE_TYPE_USIZE => reduce_typed!(usize),
        REDUCE_TYPE_ISIZE => reduce_typed!(isize),
        _ => 0,
    };
    acc
}

fn reduce_worker_loop(pool: &'static ReducePool, worker_index: usize) {
    let _ = pool.workers[worker_index].thread.set(thread::current());
    let slot = &pool.workers[worker_index];
    slot.park_state.store(WORKER_STATE_RUNNING, Ordering::Release);
    let mut local_epoch: u64 = 0;

    loop {
        // drain phase, take chunks until exhausted
        let n_chunks = pool.n_chunks.load(Ordering::Acquire);
        if pool.body.load(Ordering::Acquire).is_null() == false && n_chunks != 0 {
            loop {
                let idx = pool.next_chunk.fetch_add(1, Ordering::AcqRel);
                if idx >= n_chunks {
                    break;
                }
                // catch_unwind so panics don't hang the pool
                let acc = match crate::panic::catch_unwind(
                    crate::panic::AssertUnwindSafe(|| compute_reduce_chunk(pool, idx))
                ) {
                    Ok(v) => v,
                    Err(_payload) => {
                        // flag panic for re-raise; 0 avoids hang
                        pool.dispatch_panicked.store(true, Ordering::Release);
                        0
                    }
                };
                pool.results[idx].store(acc, Ordering::Release);
                pool.completed.fetch_add(1, Ordering::AcqRel);
            }
            local_epoch = pool.epoch.load(Ordering::Acquire);
            slot.seen_epoch.store(local_epoch, Ordering::Release);
        }

        // -- Spin phase -----------------------------------------------
        let mut checks = 0u32;
        let mut saw_new_epoch = false;
        loop {
            let cur = pool.epoch.load(Ordering::Acquire);
            if cur != local_epoch {
                local_epoch = cur;
                saw_new_epoch = true;
                break;
            }
            checks += 1;
            if checks >= WORKER_SPIN_BEFORE_PARK {
                break;
            }
            for _ in 0..WORKER_SPIN_BACKOFF {
                hint::spin_loop();
            }
        }
        if saw_new_epoch {
            continue;
        }

        // -- Park phase -----------------------------------------------
        slot.park_state.store(WORKER_STATE_PARKING, Ordering::SeqCst);
        let cur = pool.epoch.load(Ordering::Acquire);
        if cur != local_epoch {
            slot.park_state.store(WORKER_STATE_RUNNING, Ordering::Release);
            local_epoch = cur;
            continue;
        }
        slot.park_state.store(WORKER_STATE_PARKED, Ordering::Release);
        thread::park();
        slot.park_state.store(WORKER_STATE_RUNNING, Ordering::Release);
    }
}

#[inline]
fn acquire_reduce_slot(pool: &'static ReducePool) {
    if pool
        .dispatch_in_flight
        .compare_exchange(false, true, Ordering::Acquire, Ordering::Relaxed)
        .is_ok()
    {
        return;
    }
    loop {
        if pool
            .dispatch_in_flight
            .compare_exchange_weak(false, true, Ordering::Acquire, Ordering::Relaxed)
            .is_ok()
        {
            return;
        }
        hint::spin_loop();
    }
}

#[inline]
fn release_reduce_slot(pool: &'static ReducePool) {
    pool.dispatch_in_flight.store(false, Ordering::Release);
}

/// core reduce dispatch; caller checked threshold
fn parallel_reduce_dispatch(start: u64, end: u64, op_kind: u8, body: fn(u64) -> u64) -> u64 {
    parallel_reduce_dispatch_raw(start, end, op_kind, body as usize)
}

/// raw-address body variant; type tag picks T
fn parallel_reduce_dispatch_raw(
    start: u64,
    end: u64,
    op_kind: u8,
    body_addr: usize,
) -> u64 {
    let pool = reduce_pool();
    acquire_reduce_slot(pool);
    pool.dispatch_panicked.store(false, Ordering::Release);
    let n_workers = pool.n_workers.load(Ordering::Acquire);
    let n_chunks = n_workers + 1; // +1 for caller participation

    // stage with Relaxed; epoch Release publishes them
    pool.body
        .store(crate::ptr::with_exposed_provenance_mut::<()>(body_addr), Ordering::Relaxed);
    pool.op_kind.store(op_kind, Ordering::Relaxed);
    pool.range_start.store(start, Ordering::Relaxed);
    pool.range_end.store(end, Ordering::Relaxed);
    pool.n_chunks.store(n_chunks, Ordering::Relaxed);
    pool.next_chunk.store(0, Ordering::Relaxed);
    pool.completed.store(0, Ordering::Relaxed);
    pool.mode.store(REDUCE_MODE_INDEX, Ordering::Relaxed);
    pool.slice_ptr.store(ptr::null_mut(), Ordering::Relaxed);
    // clear stale partials for used chunks
    for i in 0..n_chunks {
        pool.results[i].store(0, Ordering::Relaxed);
    }
    // publish; Release covers staging stores
    pool.epoch.fetch_add(1, Ordering::Release);

    // wake parked workers; skip RUNNING ones
    for w in 0..n_workers {
        let slot = &pool.workers[w];
        let st = slot.park_state.load(Ordering::Acquire);
        if st != WORKER_STATE_RUNNING {
            if let Some(t) = slot.thread.get() {
                t.unpark();
            }
        }
    }

    // Caller participates as a chunk-claimer.
    loop {
        let idx = pool.next_chunk.fetch_add(1, Ordering::AcqRel);
        if idx >= n_chunks {
            break;
        }
        // catch_unwind; flag panic, re-raise after drain
        let acc = match crate::panic::catch_unwind(
            crate::panic::AssertUnwindSafe(|| compute_reduce_chunk(pool, idx))
        ) {
            Ok(v) => v,
            Err(_) => {
                pool.dispatch_panicked.store(true, Ordering::Release);
                0
            }
        };
        pool.results[idx].store(acc, Ordering::Release);
        pool.completed.fetch_add(1, Ordering::AcqRel);
    }

    // Spin-then-park-timeout for stragglers.
    let mut spin = 0u32;
    while pool.completed.load(Ordering::Acquire) < n_chunks {
        if spin < DISPATCHER_SPIN_BEFORE_PARK {
            spin += 1;
            hint::spin_loop();
        } else {
            thread::park_timeout(Duration::from_nanos(DISPATCHER_PARK_TIMEOUT_NS));
        }
    }

    // Combine all chunk partials
    let acc = combine_partials(pool, op_kind);

    // null body so spurious wakeups skip drain
    pool.body.store(ptr::null_mut(), Ordering::Release);
    let panicked = pool.dispatch_panicked.load(Ordering::Acquire);
    release_reduce_slot(pool);

    if panicked {
        crate::panic::resume_unwind(Box::new(
            "user-supplied iterator body panicked during parallel reduction"
        ));
    }
    acc
}

/// combine partials; min/max dispatch on signedness
fn combine_partials(pool: &ReducePool, op_kind: u8) -> u64 {
    let base_op = op_kind & REDUCE_OP_MASK;
    let type_tag_combine = op_kind & REDUCE_TYPE_MASK;

    // combine as float, then bit-cast to u64
    if type_tag_combine == REDUCE_TYPE_F64 {
        let n_chunks = pool.n_chunks.load(Ordering::Acquire);
        let mut acc_f: f64 = match base_op {
            REDUCE_OP_MUL => 1.0,
            REDUCE_OP_MIN => f64::INFINITY,
            REDUCE_OP_MAX => f64::NEG_INFINITY,
            _ => 0.0,
        };
        for i in 0..n_chunks {
            let bits = pool.results[i].load(Ordering::Acquire);
            let v = f64::from_bits(bits);
            acc_f = match base_op {
                REDUCE_OP_ADD => acc_f + v,
                REDUCE_OP_MUL => acc_f * v,
                REDUCE_OP_MIN => if v < acc_f { v } else { acc_f },
                REDUCE_OP_MAX => if v > acc_f { v } else { acc_f },
                _ => acc_f,
            };
        }
        return acc_f.to_bits();
    }
    if type_tag_combine == REDUCE_TYPE_F32 {
        let n_chunks = pool.n_chunks.load(Ordering::Acquire);
        let mut acc_f: f32 = match base_op {
            REDUCE_OP_MUL => 1.0,
            REDUCE_OP_MIN => f32::INFINITY,
            REDUCE_OP_MAX => f32::NEG_INFINITY,
            _ => 0.0,
        };
        for i in 0..n_chunks {
            let bits = pool.results[i].load(Ordering::Acquire) as u32;
            let v = f32::from_bits(bits);
            acc_f = match base_op {
                REDUCE_OP_ADD => acc_f + v,
                REDUCE_OP_MUL => acc_f * v,
                REDUCE_OP_MIN => if v < acc_f { v } else { acc_f },
                REDUCE_OP_MAX => if v > acc_f { v } else { acc_f },
                _ => acc_f,
            };
        }
        return acc_f.to_bits() as u64;
    }

    let combine_identity: u64 = match base_op {
        REDUCE_OP_ADD | REDUCE_OP_XOR | REDUCE_OP_OR | REDUCE_OP_COUNT => 0,
        REDUCE_OP_MUL => 1,
        REDUCE_OP_AND => !0u64,
        REDUCE_OP_MIN | REDUCE_OP_MAX => match (base_op, type_tag_combine) {
            (REDUCE_OP_MIN, REDUCE_TYPE_U64) => u64::MAX,
            (REDUCE_OP_MIN, REDUCE_TYPE_U32) => u32::MAX as u64,
            (REDUCE_OP_MIN, REDUCE_TYPE_I32) => i32::MAX as u64,
            (REDUCE_OP_MIN, REDUCE_TYPE_I64) => i64::MAX as u64,
            (REDUCE_OP_MIN, REDUCE_TYPE_USIZE) => usize::MAX as u64,
            (REDUCE_OP_MIN, REDUCE_TYPE_ISIZE) => isize::MAX as u64,
            (REDUCE_OP_MAX, REDUCE_TYPE_U64) => u64::MIN,
            (REDUCE_OP_MAX, REDUCE_TYPE_U32) => u32::MIN as u64,
            (REDUCE_OP_MAX, REDUCE_TYPE_I32) => i32::MIN as i64 as u64,
            (REDUCE_OP_MAX, REDUCE_TYPE_I64) => i64::MIN as u64,
            (REDUCE_OP_MAX, REDUCE_TYPE_USIZE) => usize::MIN as u64,
            (REDUCE_OP_MAX, REDUCE_TYPE_ISIZE) => isize::MIN as i64 as u64,
            _ => 0,
        },
        _ => 0,
    };
    let mut acc = combine_identity;
    let n_chunks = pool.n_chunks.load(Ordering::Acquire);
    for i in 0..n_chunks {
        let partial = pool.results[i].load(Ordering::Acquire);
        match base_op {
            // COUNT and ADD share the same combine
            REDUCE_OP_ADD | REDUCE_OP_COUNT => acc = acc.wrapping_add(partial),
            REDUCE_OP_XOR => acc ^= partial,
            REDUCE_OP_MUL => acc = acc.wrapping_mul(partial),
            REDUCE_OP_AND => acc &= partial,
            REDUCE_OP_OR => acc |= partial,
            REDUCE_OP_MIN => {
                acc = match type_tag_combine {
                    REDUCE_TYPE_U64 => u64::min(acc, partial),
                    REDUCE_TYPE_U32 => u32::min(acc as u32, partial as u32) as u64,
                    REDUCE_TYPE_I32 => i32::min(acc as i32, partial as i32) as i64 as u64,
                    REDUCE_TYPE_I64 => i64::min(acc as i64, partial as i64) as u64,
                    REDUCE_TYPE_USIZE => usize::min(acc as usize, partial as usize) as u64,
                    REDUCE_TYPE_ISIZE => isize::min(acc as isize, partial as isize) as i64 as u64,
                    _ => acc,
                };
            }
            REDUCE_OP_MAX => {
                acc = match type_tag_combine {
                    REDUCE_TYPE_U64 => u64::max(acc, partial),
                    REDUCE_TYPE_U32 => u32::max(acc as u32, partial as u32) as u64,
                    REDUCE_TYPE_I32 => i32::max(acc as i32, partial as i32) as i64 as u64,
                    REDUCE_TYPE_I64 => i64::max(acc as i64, partial as i64) as u64,
                    REDUCE_TYPE_USIZE => usize::max(acc as usize, partial as usize) as u64,
                    REDUCE_TYPE_ISIZE => isize::max(acc as isize, partial as isize) as i64 as u64,
                    _ => acc,
                };
            }
            _ => {}
        }
    }
    acc
}

/// parallel reduce with `wrapping_add`, identity 0
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_parallel_reduce_add_u64")]
#[rustc_nounwind]
pub fn parallel_reduce_add_u64(start: u64, end: u64, body: fn(u64) -> u64) -> u64 {
    let total = end.saturating_sub(start);
    if total == 0 {
        return 0;
    }
    if total < PARALLEL_REDUCE_THRESHOLD {
        return parallel_reduce_serial(start, end, 0, u64::wrapping_add, body);
    }
    parallel_reduce_dispatch(start, end, REDUCE_OP_ADD, body)
}

/// Parallel reduction with `^`
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_parallel_reduce_xor_u64")]
#[rustc_nounwind]
pub fn parallel_reduce_xor_u64(start: u64, end: u64, body: fn(u64) -> u64) -> u64 {
    let total = end.saturating_sub(start);
    if total == 0 {
        return 0;
    }
    if total < PARALLEL_REDUCE_THRESHOLD {
        return parallel_reduce_serial(start, end, 0, |a, b| a ^ b, body);
    }
    parallel_reduce_dispatch(start, end, REDUCE_OP_XOR, body)
}

// typed reduce macro; bit patterns survive u64

macro_rules! make_typed_reduce {
    ($name:ident, $diag:literal, $T:ty, $type_tag:expr, $op_kind:expr,
     $init:expr, $serial_op:expr) => {
        #[doc(hidden)]
        #[unstable(feature = "parallel_runtime_internal", issue = "none")]
        #[cfg_attr(not(test), rustc_diagnostic_item = $diag)]
        // unwind stays enabled so body panics propagate
        #[inline]
        pub fn $name(start: $T, end: $T, body: fn($T) -> $T) -> $T {
            let total = (end as i64).wrapping_sub(start as i64) as u64;
            // Empty / inverted range
            if start >= end {
                return $init;
            }
            // Serial fallback for small ranges
            if total < PARALLEL_REDUCE_THRESHOLD {
                let mut acc: $T = $init;
                let mut i: $T = start;
                while i < end {
                    acc = $serial_op(acc, body(i));
                    i = i.wrapping_add(1 as $T);
                }
                return acc;
            }
            // Cast fn pointer to address
            let body_addr = body as usize;
            // sign-extend via i64 to keep negatives
            let start_u64 = start as i64 as u64;
            let end_u64 = end as i64 as u64;
            let result = parallel_reduce_dispatch_raw(
                start_u64,
                end_u64,
                $op_kind | $type_tag,
                body_addr,
            );
            // Truncate the u64 partial back to $T
            result as $T
        }
    };
}

