// slice-source reductions; fn body can't capture slice

// typed slice reduce macro; shared dispatch, combine

macro_rules! make_typed_slice_reduce {
    ($name:ident, $diag:literal, $T:ty, $type_tag:expr, $op_kind:expr,
     $init:expr, $serial_op:expr) => {
        // inline so serial small-N path autovectorizes
        #[doc(hidden)]
        #[unstable(feature = "parallel_runtime_internal", issue = "none")]
        #[cfg_attr(not(test), rustc_diagnostic_item = $diag)]
        #[rustc_nounwind]
        #[inline]
        pub fn $name(slice: &[$T]) -> $T {
            let n = slice.len() as u64;
            if n == 0 {
                return $init;
            }
            if n < PARALLEL_REDUCE_THRESHOLD {
                // Inline serial fast path - autovectorizes
                let mut acc: $T = $init;
                let mut i = 0usize;
                while i < slice.len() {
                    acc = $serial_op(acc, slice[i]);
                    i = i.wrapping_add(1);
                }
                return acc;
            }
            let result_u64 = parallel_reduce_slice_dispatch(
                slice.as_ptr() as usize,
                n,
                $op_kind | $type_tag,
            );
            result_u64 as $T
        }
    };
}

