// float reductions, opt-in only; bit-cast, no wrapping
macro_rules! make_typed_slice_reduce_float {
    ($name:ident, $diag:literal, $T:ty, $type_tag:expr, $op_kind:expr,
     $init:expr, $serial_op:expr, $bits_to_t:path) => {
        #[doc(hidden)]
        #[unstable(feature = "parallel_runtime_internal", issue = "none")]
        #[cfg_attr(not(test), rustc_diagnostic_item = $diag)]
        #[rustc_nounwind]
        #[inline]
        pub fn $name(slice: &[$T]) -> $T {
            let n = slice.len() as u64;
            if n == 0 {
                return $init;
            }
            // Plain sum is memory-bound
            if n < PARALLEL_REDUCE_THRESHOLD_PLAIN_SUM {
                return slice.iter().copied().fold($init, $serial_op);
            }
            let result_bits = parallel_reduce_slice_dispatch(
                slice.as_ptr() as usize,
                n,
                $op_kind | $type_tag,
            );
            $bits_to_t(result_bits)
        }
    };
}

