// filter+count; u64 internally, narrowed to usize
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(
    not(test),
    rustc_diagnostic_item = "parallel_runtime_parallel_reduce_count_slice_filter_u64"
)]
#[rustc_nounwind]
pub fn parallel_reduce_count_slice_filter_u64(
    slice: &[u64],
    predicate: fn(&&u64) -> bool,
) -> usize {
    let n = slice.len() as u64;
    if n == 0 {
        return 0;
    }
    if n < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
        let mut acc: u64 = 0;
        let mut i = 0usize;
        while i < slice.len() {
            let v_ref = &slice[i];
            if predicate(&v_ref) {
                acc = acc.wrapping_add(1);
            }
            i = i.wrapping_add(1);
        }
        return acc as usize;
    }
    let result = parallel_reduce_filter_dispatch(
        slice.as_ptr() as usize,
        n,
        predicate as usize,
        REDUCE_OP_COUNT | REDUCE_TYPE_U64,
    );
    result as usize
}

// zip helpers; zip_mul vectorizes, zip_map indirect
#[cold]
#[inline(never)]
fn parallel_reduce_zip_dispatch(
    slice_a_addr: usize,
    slice_b_addr: usize,
    n: u64,
    body_addr: usize,
    op_kind_with_type: u8,
    mode: u8,
) -> u64 {
    let pool = reduce_pool();
    acquire_reduce_slot(pool);
    pool.dispatch_panicked.store(false, Ordering::Release);
    let n_workers = pool.n_workers.load(Ordering::Acquire);
    let n_chunks = n_workers + 1;

    pool.slice_ptr
        .store(crate::ptr::with_exposed_provenance_mut::<()>(slice_a_addr), Ordering::Relaxed);
    if mode == REDUCE_MODE_ZIP_MAP {
        pool.body
            .store(crate::ptr::with_exposed_provenance_mut::<()>(body_addr), Ordering::Relaxed);
        pool.closure_ctx.store(slice_b_addr, Ordering::Relaxed);
    } else {
        // ZIP_MUL: body slot holds b's slice base.
        pool.body
            .store(crate::ptr::with_exposed_provenance_mut::<()>(slice_b_addr), Ordering::Relaxed);
    }
    pool.op_kind.store(op_kind_with_type, Ordering::Relaxed);
    pool.range_start.store(0, Ordering::Relaxed);
    pool.range_end.store(n, Ordering::Relaxed);
    pool.n_chunks.store(n_chunks, Ordering::Relaxed);
    pool.next_chunk.store(0, Ordering::Relaxed);
    pool.completed.store(0, Ordering::Relaxed);
    pool.mode.store(mode, Ordering::Relaxed);
    for i in 0..n_chunks {
        pool.results[i].store(0, Ordering::Relaxed);
    }
    pool.epoch.fetch_add(1, Ordering::Release);

    for w in 0..n_workers {
        let slot = &pool.workers[w];
        let st = slot.park_state.load(Ordering::Acquire);
        if st != WORKER_STATE_RUNNING {
            if let Some(t) = slot.thread.get() {
                t.unpark();
            }
        }
    }

    loop {
        let idx = pool.next_chunk.fetch_add(1, Ordering::AcqRel);
        if idx >= n_chunks {
            break;
        }
        // catch_unwind; flag panic, re-raise after drain
        let acc = match crate::panic::catch_unwind(
            crate::panic::AssertUnwindSafe(|| compute_reduce_chunk(pool, idx))
        ) {
            Ok(v) => v,
            Err(_) => {
                pool.dispatch_panicked.store(true, Ordering::Release);
                0
            }
        };
        pool.results[idx].store(acc, Ordering::Release);
        pool.completed.fetch_add(1, Ordering::AcqRel);
    }

    let mut spin = 0u32;
    while pool.completed.load(Ordering::Acquire) < n_chunks {
        if spin < DISPATCHER_SPIN_BEFORE_PARK {
            spin += 1;
            hint::spin_loop();
        } else {
            thread::park_timeout(Duration::from_nanos(DISPATCHER_PARK_TIMEOUT_NS));
        }
    }

    let acc = combine_partials(pool, op_kind_with_type);
    pool.body.store(ptr::null_mut(), Ordering::Release);
    pool.slice_ptr.store(ptr::null_mut(), Ordering::Release);
    pool.closure_ctx.store(0, Ordering::Release);
    let panicked = pool.dispatch_panicked.load(Ordering::Acquire);
    release_reduce_slot(pool);
    if panicked {
        crate::panic::resume_unwind(Box::new(
            "user-supplied iterator body panicked during parallel reduction"
        ));
    }
    acc
}

macro_rules! make_typed_slice_zip_mul_reduce {
    ($name:ident, $diag:literal, $T:ty, $type_tag:expr) => {
        #[doc(hidden)]
        #[unstable(feature = "parallel_runtime_internal", issue = "none")]
        #[cfg_attr(not(test), rustc_diagnostic_item = $diag)]
        #[rustc_nounwind]
        #[inline]
        pub fn $name(a: &[$T], b: &[$T]) -> $T {
            let n = core::cmp::min(a.len(), b.len()) as u64;
            if n == 0 {
                return 0 as $T;
            }
            if n < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
                // Tight serial fallback - also vectorizable
                let mut acc: $T = 0 as $T;
                let mut i = 0usize;
                let stop = n as usize;
                while i < stop {
                    acc = acc.wrapping_add(a[i].wrapping_mul(b[i]));
                    i = i.wrapping_add(1);
                }
                return acc;
            }
            let result = parallel_reduce_zip_dispatch(
                a.as_ptr() as usize,
                b.as_ptr() as usize,
                n,
                0,
                REDUCE_OP_ADD | $type_tag,
                REDUCE_MODE_ZIP_MUL,
            );
            result as $T
        }
    };
}

make_typed_slice_zip_mul_reduce!(parallel_reduce_sum_slice_zip_mul_u64,
    "parallel_runtime_parallel_reduce_sum_slice_zip_mul_u64",
    u64, REDUCE_TYPE_U64);
make_typed_slice_zip_mul_reduce!(parallel_reduce_sum_slice_zip_mul_u32,
    "parallel_runtime_parallel_reduce_sum_slice_zip_mul_u32",
    u32, REDUCE_TYPE_U32);
make_typed_slice_zip_mul_reduce!(parallel_reduce_sum_slice_zip_mul_i64,
    "parallel_runtime_parallel_reduce_sum_slice_zip_mul_i64",
    i64, REDUCE_TYPE_I64);
make_typed_slice_zip_mul_reduce!(parallel_reduce_sum_slice_zip_mul_i32,
    "parallel_runtime_parallel_reduce_sum_slice_zip_mul_i32",
    i32, REDUCE_TYPE_I32);

// float variant, opt-in since add non-associative
macro_rules! make_typed_slice_zip_mul_reduce_float {
    ($name:ident, $diag:literal, $T:ty, $type_tag:expr) => {
        #[doc(hidden)]
        #[unstable(feature = "parallel_runtime_internal", issue = "none")]
        #[cfg_attr(not(test), rustc_diagnostic_item = $diag)]
        #[rustc_nounwind]
        #[inline]
        pub fn $name(a: &[$T], b: &[$T]) -> $T {
            let n = core::cmp::min(a.len(), b.len()) as u64;
            if n == 0 {
                return 0.0 as $T;
            }
            if n < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
                let mut acc: $T = 0.0 as $T;
                let mut i = 0usize;
                let stop = n as usize;
                while i < stop {
                    acc = acc + a[i] * b[i];
                    i = i.wrapping_add(1);
                }
                return acc;
            }
            let result = parallel_reduce_zip_dispatch(
                a.as_ptr() as usize,
                b.as_ptr() as usize,
                n,
                0,
                REDUCE_OP_ADD | $type_tag,
                REDUCE_MODE_ZIP_MUL,
            );
            // Worker side returns f64 / f32 bit-pattern
            <$T>::from_bits(result as <$T as FloatBits>::Bits)
        }
    };
}

// picks `from_bits` width per float type
trait FloatBits {
    type Bits;
}
impl FloatBits for f32 { type Bits = u32; }
impl FloatBits for f64 { type Bits = u64; }

make_typed_slice_zip_mul_reduce_float!(parallel_reduce_sum_slice_zip_mul_f64,
    "parallel_runtime_parallel_reduce_sum_slice_zip_mul_f64",
    f64, REDUCE_TYPE_F64);

