// iter_mut for_each; disjoint chunks, no aliasing
macro_rules! make_typed_slice_for_each_mut {
    ($name:ident, $diag:literal, $T:ty, $type_tag:expr) => {
        #[doc(hidden)]
        #[unstable(feature = "parallel_runtime_internal", issue = "none")]
        #[cfg_attr(not(test), rustc_diagnostic_item = $diag)]
        #[inline]
        pub fn $name(slice: &mut [$T], body: fn(&mut $T)) {
            let n = slice.len() as u64;
            if n == 0 {
                return;
            }
            if n < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
                let mut i = 0usize;
                while i < slice.len() {
                    body(&mut slice[i]);
                    i = i.wrapping_add(1);
                }
                return;
            }
            parallel_for_each_slice_dispatch(
                slice.as_mut_ptr() as usize,
                n,
                body as usize,
                $type_tag,
                REDUCE_MODE_FOR_EACH_MUT,
            );
        }
    };
}
make_typed_slice_for_each_mut!(parallel_for_each_mut_slice_u64,
    "parallel_runtime_parallel_for_each_mut_slice_u64", u64, REDUCE_TYPE_U64);
make_typed_slice_for_each_mut!(parallel_for_each_mut_slice_u32,
    "parallel_runtime_parallel_for_each_mut_slice_u32", u32, REDUCE_TYPE_U32);
make_typed_slice_for_each_mut!(parallel_for_each_mut_slice_i64,
    "parallel_runtime_parallel_for_each_mut_slice_i64", i64, REDUCE_TYPE_I64);
