macro_rules! make_typed_slice_map_collect {
    ($name:ident, $diag:literal, $T:ty, $type_tag:expr, $default:expr) => {
        #[doc(hidden)]
        #[unstable(feature = "parallel_runtime_internal", issue = "none")]
        #[cfg_attr(not(test), rustc_diagnostic_item = $diag)]
        #[inline]
        pub fn $name(slice: &[$T], body: fn(&$T) -> $T) -> Vec<$T> {
            let n = slice.len();
            if n == 0 {
                return Vec::new();
            }
            if (n as u64) < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
                let mut out: Vec<$T> = Vec::with_capacity(n);
                let mut i = 0usize;
                while i < n {
                    out.push(body(&slice[i]));
                    i = i.wrapping_add(1);
                }
                return out;
            }
            let mut out: Vec<$T> = vec![$default; n];
            let out_ptr = out.as_mut_ptr() as usize;
            let in_ptr = slice.as_ptr() as usize;
            parallel_collect_dispatch(
                out_ptr,
                in_ptr,
                n as u64,
                body as usize,
                $type_tag,
                REDUCE_MODE_SLICE_MAP_COLLECT,
            );
            out
        }
    };
}
