// closure map reduce, per-F trampoline, u64 only

#[cold]
#[inline(never)]
fn parallel_reduce_closure_map_dispatch(
    slice_ptr_addr: usize,
    n: u64,
    body_addr: usize,
    closure_ctx_addr: usize,
    op_kind_with_type: u8,
) -> u64 {
    let pool = reduce_pool();
    acquire_reduce_slot(pool);
    pool.dispatch_panicked.store(false, Ordering::Release);
    let n_workers = pool.n_workers.load(Ordering::Acquire);
    let n_chunks = n_workers + 1;

    pool.body
        .store(crate::ptr::with_exposed_provenance_mut::<()>(body_addr), Ordering::Relaxed);
    pool.slice_ptr
        .store(crate::ptr::with_exposed_provenance_mut::<()>(slice_ptr_addr), Ordering::Relaxed);
    pool.closure_ctx.store(closure_ctx_addr, Ordering::Relaxed);
    pool.op_kind.store(op_kind_with_type, Ordering::Relaxed);
    pool.range_start.store(0, Ordering::Relaxed);
    pool.range_end.store(n, Ordering::Relaxed);
    pool.n_chunks.store(n_chunks, Ordering::Relaxed);
    pool.next_chunk.store(0, Ordering::Relaxed);
    pool.completed.store(0, Ordering::Relaxed);
    pool.mode.store(REDUCE_MODE_CLOSURE_MAP, Ordering::Relaxed);
    for i in 0..n_chunks {
        pool.results[i].store(0, Ordering::Relaxed);
    }
    pool.epoch.fetch_add(1, Ordering::Release);

    for w in 0..n_workers {
        let slot = &pool.workers[w];
        let st = slot.park_state.load(Ordering::Acquire);
        if st != WORKER_STATE_RUNNING {
            if let Some(t) = slot.thread.get() {
                t.unpark();
            }
        }
    }

    loop {
        let idx = pool.next_chunk.fetch_add(1, Ordering::AcqRel);
        if idx >= n_chunks {
            break;
        }
        // catch body panic; dispatcher re-raises after drain
        let acc = match crate::panic::catch_unwind(
            crate::panic::AssertUnwindSafe(|| compute_reduce_chunk(pool, idx))
        ) {
            Ok(v) => v,
            Err(_) => {
                pool.dispatch_panicked.store(true, Ordering::Release);
                0
            }
        };
        pool.results[idx].store(acc, Ordering::Release);
        pool.completed.fetch_add(1, Ordering::AcqRel);
    }

    let mut spin = 0u32;
    while pool.completed.load(Ordering::Acquire) < n_chunks {
        if spin < DISPATCHER_SPIN_BEFORE_PARK {
            spin += 1;
            hint::spin_loop();
        } else {
            thread::park_timeout(Duration::from_nanos(DISPATCHER_PARK_TIMEOUT_NS));
        }
    }

    let acc = combine_partials(pool, op_kind_with_type);

    pool.body.store(ptr::null_mut(), Ordering::Release);
    pool.slice_ptr.store(ptr::null_mut(), Ordering::Release);
    pool.closure_ctx.store(0, Ordering::Release);
    let panicked = pool.dispatch_panicked.load(Ordering::Acquire);
    release_reduce_slot(pool);
    if panicked {
        crate::panic::resume_unwind(Box::new(
            "user-supplied iterator body panicked during parallel reduction"
        ));
    }
    acc
}

/// Parallel u64 map-sum over capturing Sync closure
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(
    not(test),
    rustc_diagnostic_item = "parallel_runtime_parallel_reduce_sum_slice_map_closure_u64"
)]
pub fn parallel_reduce_sum_slice_map_closure_u64<F>(slice: &[u64], closure: F) -> u64
where
    F: Fn(&u64) -> u64 + Sync,
{
    extern "C" fn trampoline<F>(ctx: usize, item: usize) -> u64
    where
        F: Fn(&u64) -> u64,
    {
        // SAFETY: closure pinned during dispatch, item in-bounds
        unsafe {
            let f: &F = &*crate::ptr::with_exposed_provenance::<F>(ctx);
            let item_ref: &u64 = &*crate::ptr::with_exposed_provenance::<u64>(item);
            f(item_ref)
        }
    }

    let n = slice.len() as u64;
    if n == 0 {
        return 0;
    }
    if n < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
        // serial fallback for small slices, no threads
        let mut acc = 0u64;
        for x in slice {
            acc = acc.wrapping_add(closure(x));
        }
        return acc;
    }
    // Pin the closure on this stack frame
    let closure_ref: &F = &closure;
    let closure_ctx_addr = (closure_ref as *const F as *const u8).expose_provenance();
    let body_addr = (trampoline::<F> as *const ()).expose_provenance();
    let result = parallel_reduce_closure_map_dispatch(
        slice.as_ptr() as usize,
        n,
        body_addr,
        closure_ctx_addr,
        REDUCE_OP_ADD | REDUCE_TYPE_U64,
    );
    result as u64
}

/// Dyn-Fn variant; generic Call from matcher ICEs
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(
    not(test),
    rustc_diagnostic_item = "parallel_runtime_parallel_reduce_sum_slice_map_closure_dyn_u64"
)]
pub fn parallel_reduce_sum_slice_map_closure_dyn_u64(
    slice: &[u64],
    closure: &(dyn Fn(&u64) -> u64 + Sync),
) -> u64 {
    extern "C" fn trampoline(ctx: usize, item: usize) -> u64 {
        // SAFETY: ctx pinned wide ref, item in-bounds
        unsafe {
            let f_ref_ptr =
                crate::ptr::with_exposed_provenance::<&(dyn Fn(&u64) -> u64 + Sync)>(ctx);
            let f: &(dyn Fn(&u64) -> u64 + Sync) = *f_ref_ptr;
            let item_ref: &u64 = &*crate::ptr::with_exposed_provenance::<u64>(item);
            f(item_ref)
        }
    }

    let n = slice.len() as u64;
    if n == 0 {
        return 0;
    }
    if n < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
        let mut acc = 0u64;
        for x in slice {
            acc = acc.wrapping_add(closure(x));
        }
        return acc;
    }
    // pin wide ref; valid while we block
    let closure_ref_pinned: &&(dyn Fn(&u64) -> u64 + Sync) = &closure;
    let closure_ctx_addr =
        (closure_ref_pinned as *const _ as *const u8).expose_provenance();
    let body_addr = (trampoline as *const ()).expose_provenance();
    let result = parallel_reduce_closure_map_dispatch(
        slice.as_ptr() as usize,
        n,
        body_addr,
        closure_ctx_addr,
        REDUCE_OP_ADD | REDUCE_TYPE_U64,
    );
    result as u64
}

// Typed dyn-Fn closure-with-captures helpers
macro_rules! make_typed_slice_map_closure_dyn_reduce {
    ($name:ident, $diag:literal, $T:ty, $type_tag:expr, $op_kind:expr,
     $init:expr, $serial_op:expr) => {
        #[doc(hidden)]
        #[unstable(feature = "parallel_runtime_internal", issue = "none")]
        #[cfg_attr(not(test), rustc_diagnostic_item = $diag)]
        #[inline]
        pub fn $name(
            slice: &[$T],
            closure: &(dyn Fn(&$T) -> $T + Sync),
        ) -> $T {
            extern "C" fn trampoline(ctx: usize, item: usize) -> u64 {
                // SAFETY: ctx pinned wide ref, item in-bounds
                unsafe {
                    let f_ref_ptr = crate::ptr::with_exposed_provenance::<
                        &(dyn Fn(&$T) -> $T + Sync),
                    >(ctx);
                    let f: &(dyn Fn(&$T) -> $T + Sync) = *f_ref_ptr;
                    let item_ref: &$T =
                        &*crate::ptr::with_exposed_provenance::<$T>(item);
                    f(item_ref) as u64
                }
            }

            let n = slice.len() as u64;
            if n == 0 {
                return $init;
            }
            if n < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
                let mut acc: $T = $init;
                for x in slice {
                    acc = $serial_op(acc, closure(x));
                }
                return acc;
            }
            let closure_ref_pinned: &&(dyn Fn(&$T) -> $T + Sync) = &closure;
            let closure_ctx_addr =
                (closure_ref_pinned as *const _ as *const u8).expose_provenance();
            let body_addr = (trampoline as *const ()).expose_provenance();
            let result = parallel_reduce_closure_map_dispatch(
                slice.as_ptr() as usize,
                n,
                body_addr,
                closure_ctx_addr,
                $op_kind | $type_tag,
            );
            result as $T
        }
    };
}

