// direct 3/4-way invoke; cascading lost inner parallelism

/// Claim N idle slots; all-or-nothing
#[inline]
fn try_acquire_invoke_workers(pool: &InvokePool, n: usize) -> Option<[usize; 3]> {
    debug_assert!(n <= 3, "current direct N-way supports up to 4-way (3 workers + caller)");
    let mut slots = [0usize; 3];
    let mut acquired = 0usize;
    for slot_pos in 0..n {
        match try_acquire_invoke_worker(pool) {
            Some(idx) => {
                slots[slot_pos] = idx;
                acquired += 1;
            }
            None => {
                for i in 0..acquired {
                    pool.workers[slots[i]].state.store(INVOKE_IDLE, Ordering::Release);
                }
                return None;
            }
        }
    }
    Some(slots)
}

/// 3-way invoke, f3 on caller, busy fallback
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_parallel_invoke_3")]
pub fn parallel_invoke_3<F1, F2, F3, R1, R2, R3>(
    f1: F1,
    f2: F2,
    f3: F3,
) -> (R1, R2, R3)
where
    F1: FnOnce() -> R1 + Send,
    F2: FnOnce() -> R2 + Send,
    F3: FnOnce() -> R3 + Send,
    R1: Send,
    R2: Send,
    R3: Send,
{
    use crate::panic::{AssertUnwindSafe, catch_unwind};
    use crate::thread::Result as ThreadResult;


    // No-thread / max-depth nested-worker fast path
    let _depth_guard = NestedInvokeDepthGuard::new();
    if !PARALLEL_RUNTIME_HAS_THREADS || _depth_guard.prev >= MAX_NESTED_INVOKE_DEPTH {
        let r1 = catch_unwind(AssertUnwindSafe(f1));
        let r2 = catch_unwind(AssertUnwindSafe(f2));
        let r3 = catch_unwind(AssertUnwindSafe(f3));
        return resolve_invoke_results_3(r1, r2, r3);
    }

    struct Task<F, R> {
        f: ManuallyDrop<F>,
        result: MaybeUninit<ThreadResult<R>>,
    }

    extern "C" fn trampoline<F, R>(task_ptr: usize)
    where
        F: FnOnce() -> R,
    {
        unsafe {
            let task_ref: *mut Task<F, R> =
                crate::ptr::with_exposed_provenance_mut::<Task<F, R>>(task_ptr);
            let task = &mut *task_ref;
            let f = ManuallyDrop::take(&mut task.f);
            let r = catch_unwind(AssertUnwindSafe(f));
            task.result.write(r);
        }
    }

    let pool = invoke_pool();
    let mut task1: Task<F1, R1> = Task { f: ManuallyDrop::new(f1), result: MaybeUninit::uninit() };
    let mut task2: Task<F2, R2> = Task { f: ManuallyDrop::new(f2), result: MaybeUninit::uninit() };

    // Claim 2 workers atomically (or fall back).
    let workers = match try_acquire_invoke_workers(pool, 2) {
        Some(w) => w,
        None => {
            // Couldn't get 2 workers
            let f1 = unsafe { ManuallyDrop::take(&mut task1.f) };
            let f2 = unsafe { ManuallyDrop::take(&mut task2.f) };
            let (r12, r3) = parallel_invoke_2(
                move || (f1(), f2()),
                f3,
            );
            let (r1_v, r2_v) = r12;
            return (r1_v, r2_v, r3);
        }
    };
    let w_a = workers[0];
    let w_b = workers[1];

    // Publish task to worker A.
    {
        let slot = &pool.workers[w_a];
        slot.trampoline.store(trampoline::<F1, R1> as *mut (), Ordering::Relaxed);
        slot.task_ptr.store(
            (&mut task1 as *mut Task<F1, R1>).expose_provenance(),
            Ordering::Relaxed,
        );
        slot.state.store(INVOKE_TASK_READY, Ordering::Release);
        if slot.park_state.load(Ordering::Acquire) != WORKER_STATE_RUNNING {
            if let Some(t) = slot.thread.get() {
                t.unpark();
            }
        }
    }
    // Publish task to worker B.
    {
        let slot = &pool.workers[w_b];
        slot.trampoline.store(trampoline::<F2, R2> as *mut (), Ordering::Relaxed);
        slot.task_ptr.store(
            (&mut task2 as *mut Task<F2, R2>).expose_provenance(),
            Ordering::Relaxed,
        );
        slot.state.store(INVOKE_TASK_READY, Ordering::Release);
        if slot.park_state.load(Ordering::Acquire) != WORKER_STATE_RUNNING {
            if let Some(t) = slot.thread.get() {
                t.unpark();
            }
        }
    }

    // Run f3 inline on caller.
    let r3 = catch_unwind(AssertUnwindSafe(f3));

    // Wait for both workers
    let mut spins = 0u32;
    loop {
        let a_done = pool.workers[w_a].state.load(Ordering::Acquire) == INVOKE_DONE;
        let b_done = pool.workers[w_b].state.load(Ordering::Acquire) == INVOKE_DONE;
        if a_done && b_done {
            break;
        }
        spins += 1;
        if spins >= DISPATCHER_SPIN_BEFORE_PARK {
            thread::park_timeout(Duration::from_nanos(DISPATCHER_PARK_TIMEOUT_NS));
            spins = 0;
        } else {
            hint::spin_loop();
        }
    }

    let r1 = unsafe { task1.result.assume_init() };
    let r2 = unsafe { task2.result.assume_init() };
    pool.workers[w_a].state.store(INVOKE_IDLE, Ordering::Release);
    pool.workers[w_b].state.store(INVOKE_IDLE, Ordering::Release);

    resolve_invoke_results_3(r1, r2, r3)
}

#[inline]
fn resolve_invoke_results_3<R1, R2, R3>(
    r1: crate::thread::Result<R1>,
    r2: crate::thread::Result<R2>,
    r3: crate::thread::Result<R3>,
) -> (R1, R2, R3) {
    match (r1, r2, r3) {
        (Ok(v1), Ok(v2), Ok(v3)) => (v1, v2, v3),
        // f3 panicked - has priority
        (r1_, r2_, Err(p)) => {
            if let Ok(v) = r1_ { drop(v); }
            if let Ok(v) = r2_ { drop(v); }
            crate::panic::resume_unwind(p)
        }
        // f2 panicked.
        (r1_, Err(p), Ok(v3)) => {
            if let Ok(v) = r1_ { drop(v); }
            drop(v3);
            crate::panic::resume_unwind(p)
        }
        // f1 panicked.
        (Err(p), Ok(v2), Ok(v3)) => {
            drop(v2);
            drop(v3);
            crate::panic::resume_unwind(p)
        }
    }
}

/// 4-way invoke, f4 on caller, busy fallback
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_parallel_invoke_4")]
pub fn parallel_invoke_4<F1, F2, F3, F4, R1, R2, R3, R4>(
    f1: F1,
    f2: F2,
    f3: F3,
    f4: F4,
) -> (R1, R2, R3, R4)
where
    F1: FnOnce() -> R1 + Send,
    F2: FnOnce() -> R2 + Send,
    F3: FnOnce() -> R3 + Send,
    F4: FnOnce() -> R4 + Send,
    R1: Send,
    R2: Send,
    R3: Send,
    R4: Send,
{
    use crate::panic::{AssertUnwindSafe, catch_unwind};
    use crate::thread::Result as ThreadResult;


    // See parallel_invoke_2 for the depth-counter rationale.
    let _depth_guard = NestedInvokeDepthGuard::new();
    if !PARALLEL_RUNTIME_HAS_THREADS || _depth_guard.prev >= MAX_NESTED_INVOKE_DEPTH {
        let r1 = catch_unwind(AssertUnwindSafe(f1));
        let r2 = catch_unwind(AssertUnwindSafe(f2));
        let r3 = catch_unwind(AssertUnwindSafe(f3));
        let r4 = catch_unwind(AssertUnwindSafe(f4));
        return resolve_invoke_results_4(r1, r2, r3, r4);
    }

    struct Task<F, R> {
        f: ManuallyDrop<F>,
        result: MaybeUninit<ThreadResult<R>>,
    }
    extern "C" fn trampoline<F, R>(task_ptr: usize)
    where
        F: FnOnce() -> R,
    {
        unsafe {
            let task_ref: *mut Task<F, R> =
                crate::ptr::with_exposed_provenance_mut::<Task<F, R>>(task_ptr);
            let task = &mut *task_ref;
            let f = ManuallyDrop::take(&mut task.f);
            let r = catch_unwind(AssertUnwindSafe(f));
            task.result.write(r);
        }
    }

    let pool = invoke_pool();
    let mut task1: Task<F1, R1> = Task { f: ManuallyDrop::new(f1), result: MaybeUninit::uninit() };
    let mut task2: Task<F2, R2> = Task { f: ManuallyDrop::new(f2), result: MaybeUninit::uninit() };
    let mut task3: Task<F3, R3> = Task { f: ManuallyDrop::new(f3), result: MaybeUninit::uninit() };

    // Claim 3 workers atomically
    let workers = match try_acquire_invoke_workers(pool, 3) {
        Some(w) => w,
        None => {
            let f1 = unsafe { ManuallyDrop::take(&mut task1.f) };
            let f2 = unsafe { ManuallyDrop::take(&mut task2.f) };
            let f3 = unsafe { ManuallyDrop::take(&mut task3.f) };
            let (r12, (r3v, r4v)) = parallel_invoke_2(
                move || (f1(), f2()),
                move || (f3(), f4()),
            );
            let (r1v, r2v) = r12;
            return (r1v, r2v, r3v, r4v);
        }
    };
    let w_a = workers[0];
    let w_b = workers[1];
    let w_c = workers[2];

    // publish 3 tasks; explicit types for inference
    {
        let slot = &pool.workers[w_a];
        slot.trampoline.store(trampoline::<F1, R1> as *mut (), Ordering::Relaxed);
        slot.task_ptr.store(
            (&mut task1 as *mut Task<F1, R1>).expose_provenance(),
            Ordering::Relaxed,
        );
        slot.state.store(INVOKE_TASK_READY, Ordering::Release);
        if slot.park_state.load(Ordering::Acquire) != WORKER_STATE_RUNNING {
            if let Some(t) = slot.thread.get() {
                t.unpark();
            }
        }
    }
    {
        let slot = &pool.workers[w_b];
        slot.trampoline.store(trampoline::<F2, R2> as *mut (), Ordering::Relaxed);
        slot.task_ptr.store(
            (&mut task2 as *mut Task<F2, R2>).expose_provenance(),
            Ordering::Relaxed,
        );
        slot.state.store(INVOKE_TASK_READY, Ordering::Release);
        if slot.park_state.load(Ordering::Acquire) != WORKER_STATE_RUNNING {
            if let Some(t) = slot.thread.get() {
                t.unpark();
            }
        }
    }
    {
        let slot = &pool.workers[w_c];
        slot.trampoline.store(trampoline::<F3, R3> as *mut (), Ordering::Relaxed);
        slot.task_ptr.store(
            (&mut task3 as *mut Task<F3, R3>).expose_provenance(),
            Ordering::Relaxed,
        );
        slot.state.store(INVOKE_TASK_READY, Ordering::Release);
        if slot.park_state.load(Ordering::Acquire) != WORKER_STATE_RUNNING {
            if let Some(t) = slot.thread.get() {
                t.unpark();
            }
        }
    }

    // Run f4 inline.
    let r4 = catch_unwind(AssertUnwindSafe(f4));

    // Wait for all 3 workers.
    let mut spins = 0u32;
    loop {
        let a = pool.workers[w_a].state.load(Ordering::Acquire) == INVOKE_DONE;
        let b = pool.workers[w_b].state.load(Ordering::Acquire) == INVOKE_DONE;
        let c = pool.workers[w_c].state.load(Ordering::Acquire) == INVOKE_DONE;
        if a && b && c {
            break;
        }
        spins += 1;
        if spins >= DISPATCHER_SPIN_BEFORE_PARK {
            thread::park_timeout(Duration::from_nanos(DISPATCHER_PARK_TIMEOUT_NS));
            spins = 0;
        } else {
            hint::spin_loop();
        }
    }

    let r1 = unsafe { task1.result.assume_init() };
    let r2 = unsafe { task2.result.assume_init() };
    let r3 = unsafe { task3.result.assume_init() };
    pool.workers[w_a].state.store(INVOKE_IDLE, Ordering::Release);
    pool.workers[w_b].state.store(INVOKE_IDLE, Ordering::Release);
    pool.workers[w_c].state.store(INVOKE_IDLE, Ordering::Release);

    resolve_invoke_results_4(r1, r2, r3, r4)
}

#[inline]
fn resolve_invoke_results_4<R1, R2, R3, R4>(
    r1: crate::thread::Result<R1>,
    r2: crate::thread::Result<R2>,
    r3: crate::thread::Result<R3>,
    r4: crate::thread::Result<R4>,
) -> (R1, R2, R3, R4) {
    // panic priority descends f4 to f1
    match (r1, r2, r3, r4) {
        (Ok(v1), Ok(v2), Ok(v3), Ok(v4)) => (v1, v2, v3, v4),
        (r1_, r2_, r3_, Err(p)) => {
            if let Ok(v) = r1_ { drop(v); }
            if let Ok(v) = r2_ { drop(v); }
            if let Ok(v) = r3_ { drop(v); }
            crate::panic::resume_unwind(p)
        }
        (r1_, r2_, Err(p), Ok(v4)) => {
            if let Ok(v) = r1_ { drop(v); }
            if let Ok(v) = r2_ { drop(v); }
            drop(v4);
            crate::panic::resume_unwind(p)
        }
        (r1_, Err(p), Ok(v3), Ok(v4)) => {
            if let Ok(v) = r1_ { drop(v); }
            drop(v3); drop(v4);
            crate::panic::resume_unwind(p)
        }
        (Err(p), Ok(v2), Ok(v3), Ok(v4)) => {
            drop(v2); drop(v3); drop(v4);
            crate::panic::resume_unwind(p)
        }
    }
}

