/// 5-way parallel invoke: `parallel_invoke_4(f1..f4) || f5`.
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
pub fn parallel_invoke_5<F1, F2, F3, F4, F5, R1, R2, R3, R4, R5>(
    f1: F1, f2: F2, f3: F3, f4: F4, f5: F5,
) -> (R1, R2, R3, R4, R5)
where
    F1: FnOnce() -> R1 + Send, R1: Send,
    F2: FnOnce() -> R2 + Send, R2: Send,
    F3: FnOnce() -> R3 + Send, R3: Send,
    F4: FnOnce() -> R4 + Send, R4: Send,
    F5: FnOnce() -> R5 + Send, R5: Send,
{
    let ((r1, r2, r3, r4), r5) = parallel_invoke_2(
        move || parallel_invoke_4(f1, f2, f3, f4),
        f5,
    );
    (r1, r2, r3, r4, r5)
}

