// AXPY helpers on parallel_invoke_4, keeps impl simple

/// AXPY `y += alpha*x`, parallel above threshold
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_parallel_axpy_f64")]
#[inline]
pub fn parallel_axpy_f64(y: &mut [f64], x: &[f64], alpha: f64) {
    let n = core::cmp::min(y.len(), x.len());
    if n == 0 { return; }
    // Lower threshold than plain sums
    if (n as u64) < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
        for i in 0..n {
            y[i] = alpha * x[i] + y[i];
        }
        return;
    }
    // 4 disjoint chunks, raw ptrs via SendPtr
    let q = n / 4;
    let q1 = q;
    let q2 = q + q1;
    let q3 = q + q2;
    let yp = y.as_mut_ptr();
    let xp = x.as_ptr();
    struct SendMutPtr(*mut f64);
    struct SendConstPtr(*const f64);
    unsafe impl Send for SendMutPtr {}
    unsafe impl Send for SendConstPtr {}
    let yp_a = SendMutPtr(yp);
    let yp_b = SendMutPtr(unsafe { yp.add(q1) });
    let yp_c = SendMutPtr(unsafe { yp.add(q2) });
    let yp_d = SendMutPtr(unsafe { yp.add(q3) });
    let xp_a = SendConstPtr(xp);
    let xp_b = SendConstPtr(unsafe { xp.add(q1) });
    let xp_c = SendConstPtr(unsafe { xp.add(q2) });
    let xp_d = SendConstPtr(unsafe { xp.add(q3) });
    let len_d = n - q3;
    parallel_invoke_4(
        move || axpy_chunk_f64(yp_a, xp_a, q, alpha),
        move || axpy_chunk_f64(yp_b, xp_b, q, alpha),
        move || axpy_chunk_f64(yp_c, xp_c, q, alpha),
        move || axpy_chunk_f64(yp_d, xp_d, len_d, alpha),
    );
    #[inline(always)]
    fn axpy_chunk_f64(yp: SendMutPtr, xp: SendConstPtr, n: usize, alpha: f64) {
        // SAFETY: y chunks disjoint, x read-only
        let yp = yp.0;
        let xp = xp.0;
        for i in 0..n {
            unsafe {
                let yi = yp.add(i);
                let xi = xp.add(i);
                *yi = alpha * (*xi) + *yi;
            }
        }
    }
}

/// Parallel indexed for-each-mut over an `f64` slice
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_parallel_for_each_indexed_mut_f64")]
#[inline]
pub fn parallel_for_each_indexed_mut_f64(dest: &mut [f64], body: fn(usize) -> f64) {
    let n = dest.len();
    if n == 0 { return; }
    if (n as u64) < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
        for i in 0..n { dest[i] = body(i); }
        return;
    }
    let q = n / 4;
    let s_a = 0;
    let s_b = q;
    let s_c = q + q;
    let s_d = q + q + q;
    let e_a = s_b;
    let e_b = s_c;
    let e_c = s_d;
    let e_d = n;
    struct SendMutPtr(*mut f64);
    unsafe impl Send for SendMutPtr {}
    let dp = SendMutPtr(dest.as_mut_ptr());
    let dp2 = SendMutPtr(dest.as_mut_ptr());
    let dp3 = SendMutPtr(dest.as_mut_ptr());
    let dp4 = SendMutPtr(dest.as_mut_ptr());
    parallel_invoke_4(
        move || iter_chunk(dp, body, s_a, e_a),
        move || iter_chunk(dp2, body, s_b, e_b),
        move || iter_chunk(dp3, body, s_c, e_c),
        move || iter_chunk(dp4, body, s_d, e_d),
    );
    #[inline(always)]
    fn iter_chunk(p: SendMutPtr, body: fn(usize) -> f64, start: usize, end: usize) {
        let p = p.0;
        for i in start..end {
            let v = body(i);
            unsafe { *p.add(i) = v; }
        }
    }
}

// unary-apply family; per-method helpers keep SIMD lowering

macro_rules! make_unary_apply_helper {
    ($name:ident, $diag:literal, $method:ident) => {
        #[doc(hidden)]
        #[unstable(feature = "parallel_runtime_internal", issue = "none")]
        #[cfg_attr(not(test), rustc_diagnostic_item = $diag)]
        #[inline]
        pub fn $name(dst: &mut [f64], a: &[f64]) {
            let n = core::cmp::min(dst.len(), a.len());
            if n == 0 { return; }
            // memory-bound; serial vectorised loop wins below threshold
            if (n as u64) < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
                for i in 0..n { dst[i] = a[i].$method(); }
                return;
            }
            let q = n / 4;
            let q1 = q; let q2 = q + q1; let q3 = q + q2;
            let dp = dst.as_mut_ptr(); let ap = a.as_ptr();
            struct SendMutPtr(*mut f64); struct SendConstPtr(*const f64);
            unsafe impl Send for SendMutPtr {} unsafe impl Send for SendConstPtr {}
            let dp_a = SendMutPtr(dp); let dp_b = SendMutPtr(unsafe { dp.add(q1) });
            let dp_c = SendMutPtr(unsafe { dp.add(q2) }); let dp_d = SendMutPtr(unsafe { dp.add(q3) });
            let ap_a = SendConstPtr(ap); let ap_b = SendConstPtr(unsafe { ap.add(q1) });
            let ap_c = SendConstPtr(unsafe { ap.add(q2) }); let ap_d = SendConstPtr(unsafe { ap.add(q3) });
            let len_d = n - q3;
            parallel_invoke_4(
                move || ck(dp_a, ap_a, q),
                move || ck(dp_b, ap_b, q),
                move || ck(dp_c, ap_c, q),
                move || ck(dp_d, ap_d, len_d),
            );
            #[inline(always)]
            fn ck(dp: SendMutPtr, ap: SendConstPtr, n: usize) {
                let dp = dp.0; let ap = ap.0;
                for i in 0..n {
                    unsafe { *dp.add(i) = (*ap.add(i)).$method(); }
                }
            }
        }
    };
}

make_unary_apply_helper!(parallel_apply_abs_f64,  "parallel_runtime_parallel_apply_abs_f64",  abs);
make_unary_apply_helper!(parallel_apply_sqrt_f64, "parallel_runtime_parallel_apply_sqrt_f64", sqrt);
make_unary_apply_helper!(parallel_apply_exp_f64,  "parallel_runtime_parallel_apply_exp_f64",  exp);
make_unary_apply_helper!(parallel_apply_ln_f64,   "parallel_runtime_parallel_apply_ln_f64",   ln);
make_unary_apply_helper!(parallel_apply_tanh_f64, "parallel_runtime_parallel_apply_tanh_f64", tanh);
make_unary_apply_helper!(parallel_apply_sin_f64,  "parallel_runtime_parallel_apply_sin_f64",  sin);
make_unary_apply_helper!(parallel_apply_cos_f64,  "parallel_runtime_parallel_apply_cos_f64",  cos);
make_unary_apply_helper!(parallel_apply_recip_f64,"parallel_runtime_parallel_apply_recip_f64",recip);
make_unary_apply_helper!(parallel_apply_floor_f64,"parallel_runtime_parallel_apply_floor_f64",floor);
make_unary_apply_helper!(parallel_apply_ceil_f64, "parallel_runtime_parallel_apply_ceil_f64", ceil);
make_unary_apply_helper!(parallel_apply_round_f64,"parallel_runtime_parallel_apply_round_f64",round);

