/// Row-major GEMV, parallel over rows
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_parallel_matvec_f64")]
#[inline]
pub fn parallel_matvec_f64(y: &mut [f64], a: &[f64], x: &[f64], m: usize, n: usize) {
    // defensive bounds on y, a, x lengths
    let m = core::cmp::min(m, y.len());
    let n_check = if let Some(prod) = m.checked_mul(n) {
        prod <= a.len()
    } else { false };
    let n = if n_check && n <= x.len() { n } else { return; };
    if m == 0 || n == 0 { return; }
    // memory-bound; parallel only pays past ~1M elements
    if ((m * n) as u64) < (1u64 << 20) || !PARALLEL_RUNTIME_HAS_THREADS {
        // Bounds were already validated above
        let yp = y.as_mut_ptr();
        let ap = a.as_ptr();
        let xp = x.as_ptr();
        for i in 0..m {
            let mut acc = 0f64;
            let base = i * n;
            for j in 0..n { unsafe { acc += *ap.add(base + j) * *xp.add(j); } }
            unsafe { *yp.add(i) = acc; }
        }
        return;
    }
    // Split rows into 8 chunks
    #[derive(Clone, Copy)]
    struct SendMutPtr(*mut f64);
    #[derive(Clone, Copy)]
    struct SendConstPtr(*const f64);
    unsafe impl Send for SendMutPtr {}
    unsafe impl Send for SendConstPtr {}
    let yw = SendMutPtr(y.as_mut_ptr());
    let aw = SendConstPtr(a.as_ptr());
    let xw = SendConstPtr(x.as_ptr());
    let q = m / 8;
    parallel_invoke_8(
        move || mv_chunk(yw, aw, xw, n, 0,     q),
        move || mv_chunk(yw, aw, xw, n, q,     q * 2),
        move || mv_chunk(yw, aw, xw, n, q * 2, q * 3),
        move || mv_chunk(yw, aw, xw, n, q * 3, q * 4),
        move || mv_chunk(yw, aw, xw, n, q * 4, q * 5),
        move || mv_chunk(yw, aw, xw, n, q * 5, q * 6),
        move || mv_chunk(yw, aw, xw, n, q * 6, q * 7),
        move || mv_chunk(yw, aw, xw, n, q * 7, m),
    );
    #[inline(always)]
    fn mv_chunk(
        yp: SendMutPtr, ap: SendConstPtr, xp: SendConstPtr,
        n: usize, i_start: usize, i_end: usize,
    ) {
        let yp = yp.0; let ap = ap.0; let xp = xp.0;
        for i in i_start..i_end {
            let mut acc = 0f64;
            let base = i * n;
            for j in 0..n {
                unsafe { acc += *ap.add(base + j) * *xp.add(j); }
            }
            unsafe { *yp.add(i) = acc; }
        }
    }
}

/// Broadcast add `a[i*n+j] += b[j]`, row-parallel
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_parallel_broadcast_add_f64")]
#[inline]
pub fn parallel_broadcast_add_f64(a: &mut [f64], b: &[f64], m: usize, n: usize) {
    let m = core::cmp::min(m, if n > 0 { a.len() / n } else { 0 });
    if n > b.len() || m == 0 || n == 0 { return; }
    if ((m * n) as u64) < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
        for i in 0..m {
            let base = i * n;
            for j in 0..n { a[base + j] += b[j]; }
        }
        return;
    }
    let q = m / 4;
    let s = [0, q, q+q, q+q+q, m];
    let ap = a.as_mut_ptr(); let bp = b.as_ptr();
    struct SendMutPtr(*mut f64); struct SendConstPtr(*const f64);
    unsafe impl Send for SendMutPtr {} unsafe impl Send for SendConstPtr {}
    let aps = [SendMutPtr(ap), SendMutPtr(ap), SendMutPtr(ap), SendMutPtr(ap)];
    let bps = [SendConstPtr(bp), SendConstPtr(bp), SendConstPtr(bp), SendConstPtr(bp)];
    let [a0, a1, a2, a3] = aps;
    let [b0, b1, b2, b3] = bps;
    parallel_invoke_4(
        move || ba_chunk(a0, b0, n, s[0], s[1]),
        move || ba_chunk(a1, b1, n, s[1], s[2]),
        move || ba_chunk(a2, b2, n, s[2], s[3]),
        move || ba_chunk(a3, b3, n, s[3], s[4]),
    );
    #[inline(always)]
    fn ba_chunk(ap: SendMutPtr, bp: SendConstPtr, n: usize, i_start: usize, i_end: usize) {
        let ap = ap.0; let bp = bp.0;
        for i in i_start..i_end {
            let base = i * n;
            for j in 0..n { unsafe { *ap.add(base + j) += *bp.add(j); } }
        }
    }
}

/// Row sums `out[i] = sum_j a[i*n+j]`, row-parallel
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_parallel_axis_reduce_sum_f64")]
#[inline]
pub fn parallel_axis_reduce_sum_f64(out: &mut [f64], a: &[f64], m: usize, n: usize) {
    let m = core::cmp::min(m, out.len());
    let n_ok = if let Some(p) = m.checked_mul(n) { p <= a.len() } else { false };
    let n = if n_ok { n } else { return; };
    if m == 0 || n == 0 { return; }
    if ((m * n) as u64) < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
        for i in 0..m {
            let base = i * n;
            let mut s = 0f64;
            for j in 0..n { s += a[base + j]; }
            out[i] = s;
        }
        return;
    }
    let q = m / 4;
    let s = [0, q, q+q, q+q+q, m];
    let op = out.as_mut_ptr(); let ap = a.as_ptr();
    struct SendMutPtr(*mut f64); struct SendConstPtr(*const f64);
    unsafe impl Send for SendMutPtr {} unsafe impl Send for SendConstPtr {}
    let ops = [SendMutPtr(op), SendMutPtr(op), SendMutPtr(op), SendMutPtr(op)];
    let aps = [SendConstPtr(ap), SendConstPtr(ap), SendConstPtr(ap), SendConstPtr(ap)];
    let [o0, o1, o2, o3] = ops;
    let [a0, a1, a2, a3] = aps;
    parallel_invoke_4(
        move || ar_chunk(o0, a0, n, s[0], s[1]),
        move || ar_chunk(o1, a1, n, s[1], s[2]),
        move || ar_chunk(o2, a2, n, s[2], s[3]),
        move || ar_chunk(o3, a3, n, s[3], s[4]),
    );
    #[inline(always)]
    fn ar_chunk(op: SendMutPtr, ap: SendConstPtr, n: usize, i_start: usize, i_end: usize) {
        let op = op.0; let ap = ap.0;
        for i in i_start..i_end {
            let base = i * n;
            let mut sum = 0f64;
            for j in 0..n { unsafe { sum += *ap.add(base + j); } }
            unsafe { *op.add(i) = sum; }
        }
    }
}

/// Transpose `b[j*m+i] = a[i*n+j]`, source-row parallel
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_parallel_transpose_f64")]
#[inline]
pub fn parallel_transpose_f64(b: &mut [f64], a: &[f64], m: usize, n: usize) {
    let need_a = if let Some(p) = m.checked_mul(n) { p } else { return; };
    let need_b = need_a;
    if a.len() < need_a || b.len() < need_b { return; }
    if m == 0 || n == 0 { return; }
    if ((m * n) as u64) < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
        for i in 0..m {
            let base = i * n;
            for j in 0..n { b[j * m + i] = a[base + j]; }
        }
        return;
    }
    let q = m / 4;
    let s = [0, q, q+q, q+q+q, m];
    let bp = b.as_mut_ptr(); let ap = a.as_ptr();
    struct SendMutPtr(*mut f64); struct SendConstPtr(*const f64);
    unsafe impl Send for SendMutPtr {} unsafe impl Send for SendConstPtr {}
    let bps = [SendMutPtr(bp), SendMutPtr(bp), SendMutPtr(bp), SendMutPtr(bp)];
    let aps = [SendConstPtr(ap), SendConstPtr(ap), SendConstPtr(ap), SendConstPtr(ap)];
    let [b0, b1, b2, b3] = bps;
    let [a0, a1, a2, a3] = aps;
    parallel_invoke_4(
        move || tr_chunk(b0, a0, m, n, s[0], s[1]),
        move || tr_chunk(b1, a1, m, n, s[1], s[2]),
        move || tr_chunk(b2, a2, m, n, s[2], s[3]),
        move || tr_chunk(b3, a3, m, n, s[3], s[4]),
    );
    #[inline(always)]
    fn tr_chunk(bp: SendMutPtr, ap: SendConstPtr, m: usize, n: usize,
                i_start: usize, i_end: usize) {
        let bp = bp.0; let ap = ap.0;
        for i in i_start..i_end {
            let base = i * n;
            for j in 0..n {
                unsafe { *bp.add(j * m + i) = *ap.add(base + j); }
            }
        }
    }
}

/// Argmin; 0 if empty; lowest tied index
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_parallel_argmin_f64")]
#[inline]
pub fn parallel_argmin_f64(slice: &[f64]) -> usize {
    let n = slice.len();
    if n == 0 { return 0; }
    if (n as u64) < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
        let mut best_v = slice[0];
        let mut best_i = 0;
        for i in 1..n {
            if slice[i] < best_v { best_v = slice[i]; best_i = i; }
        }
        return best_i;
    }
    let q = n / 4;
    let s = [0, q, q+q, q+q+q, n];
    let sp = slice.as_ptr();
    struct SendConstPtr(*const f64);
    unsafe impl Send for SendConstPtr {}
    let sps = [SendConstPtr(sp), SendConstPtr(sp), SendConstPtr(sp), SendConstPtr(sp)];
    let [s0, s1, s2, s3] = sps;
    let parts = parallel_invoke_4(
        move || am_chunk(s0, s[0], s[1]),
        move || am_chunk(s1, s[1], s[2]),
        move || am_chunk(s2, s[2], s[3]),
        move || am_chunk(s3, s[3], s[4]),
    );
    // merge partials; ties go to lower index
    let mut best = parts.0;
    for p in [parts.1, parts.2, parts.3] {
        if p.0 < best.0 || (p.0 == best.0 && p.1 < best.1) {
            best = p;
        }
    }
    return best.1;
    #[inline(always)]
    fn am_chunk(sp: SendConstPtr, start: usize, end: usize) -> (f64, usize) {
        if start >= end { return (f64::INFINITY, start); }
        let sp = sp.0;
        let mut best_v = unsafe { *sp.add(start) };
        let mut best_i = start;
        for i in (start+1)..end {
            unsafe {
                let v = *sp.add(i);
                if v < best_v { best_v = v; best_i = i; }
            }
        }
        (best_v, best_i)
    }
}

#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_parallel_argmax_f64")]
#[inline]
pub fn parallel_argmax_f64(slice: &[f64]) -> usize {
    let n = slice.len();
    if n == 0 { return 0; }
    if (n as u64) < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
        let mut best_v = slice[0];
        let mut best_i = 0;
        for i in 1..n {
            if slice[i] > best_v { best_v = slice[i]; best_i = i; }
        }
        return best_i;
    }
    let q = n / 4;
    let s = [0, q, q+q, q+q+q, n];
    let sp = slice.as_ptr();
    struct SendConstPtr(*const f64);
    unsafe impl Send for SendConstPtr {}
    let sps = [SendConstPtr(sp), SendConstPtr(sp), SendConstPtr(sp), SendConstPtr(sp)];
    let [s0, s1, s2, s3] = sps;
    let parts = parallel_invoke_4(
        move || am_chunk(s0, s[0], s[1]),
        move || am_chunk(s1, s[1], s[2]),
        move || am_chunk(s2, s[2], s[3]),
        move || am_chunk(s3, s[3], s[4]),
    );
    let mut best = parts.0;
    for p in [parts.1, parts.2, parts.3] {
        if p.0 > best.0 || (p.0 == best.0 && p.1 < best.1) {
            best = p;
        }
    }
    return best.1;
    #[inline(always)]
    fn am_chunk(sp: SendConstPtr, start: usize, end: usize) -> (f64, usize) {
        if start >= end { return (f64::NEG_INFINITY, start); }
        let sp = sp.0;
        let mut best_v = unsafe { *sp.add(start) };
        let mut best_i = start;
        for i in (start+1)..end {
            unsafe {
                let v = *sp.add(i);
                if v > best_v { best_v = v; best_i = i; }
            }
        }
        (best_v, best_i)
    }
}

/// Mask blend of `a`, `b` by `cond`
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_parallel_select_f64")]
#[inline]
pub fn parallel_select_f64(dst: &mut [f64], cond: &[bool], a: &[f64], b: &[f64]) {
    let n = core::cmp::min(dst.len(), core::cmp::min(cond.len(), core::cmp::min(a.len(), b.len())));
    if n == 0 { return; }
    if (n as u64) < PARALLEL_REDUCE_THRESHOLD_PLAIN_SUM || !PARALLEL_RUNTIME_HAS_THREADS {
        for i in 0..n { dst[i] = if cond[i] { a[i] } else { b[i] }; }
        return;
    }
    let q = n / 4;
    let q1 = q; let q2 = q + q1; let q3 = q + q2;
    let dp = dst.as_mut_ptr(); let cp = cond.as_ptr();
    let ap = a.as_ptr(); let bp = b.as_ptr();
    struct SendMutPtr(*mut f64); struct SendConstPtr<T>(*const T);
    unsafe impl Send for SendMutPtr {}
    unsafe impl<T> Send for SendConstPtr<T> {}
    let dpa = SendMutPtr(dp); let dpb = SendMutPtr(unsafe { dp.add(q1) });
    let dpc = SendMutPtr(unsafe { dp.add(q2) }); let dpd = SendMutPtr(unsafe { dp.add(q3) });
    let cpa: SendConstPtr<bool> = SendConstPtr(cp);
    let cpb = SendConstPtr(unsafe { cp.add(q1) });
    let cpc = SendConstPtr(unsafe { cp.add(q2) });
    let cpd = SendConstPtr(unsafe { cp.add(q3) });
    let apa: SendConstPtr<f64> = SendConstPtr(ap);
    let apb = SendConstPtr(unsafe { ap.add(q1) });
    let apc = SendConstPtr(unsafe { ap.add(q2) });
    let apd = SendConstPtr(unsafe { ap.add(q3) });
    let bpa: SendConstPtr<f64> = SendConstPtr(bp);
    let bpb = SendConstPtr(unsafe { bp.add(q1) });
    let bpc = SendConstPtr(unsafe { bp.add(q2) });
    let bpd = SendConstPtr(unsafe { bp.add(q3) });
    let len_d = n - q3;
    parallel_invoke_4(
        move || sel_chunk(dpa, cpa, apa, bpa, q),
        move || sel_chunk(dpb, cpb, apb, bpb, q),
        move || sel_chunk(dpc, cpc, apc, bpc, q),
        move || sel_chunk(dpd, cpd, apd, bpd, len_d),
    );
    #[inline(always)]
    fn sel_chunk(dp: SendMutPtr, cp: SendConstPtr<bool>,
                 ap: SendConstPtr<f64>, bp: SendConstPtr<f64>, n: usize) {
        let dp = dp.0; let cp = cp.0; let ap = ap.0; let bp = bp.0;
        for i in 0..n {
            unsafe {
                *dp.add(i) = if *cp.add(i) { *ap.add(i) } else { *bp.add(i) };
            }
        }
    }
}

/// 1D convolution, parallel over output positions
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_parallel_conv1d_f64")]
#[inline]
pub fn parallel_conv1d_f64(y: &mut [f64], x: &[f64], w: &[f64], n: usize, ks: usize) {
    if ks == 0 || n < ks { return; }
    let out_len = core::cmp::min(y.len(), n - ks + 1);
    if x.len() < n || w.len() < ks { return; }
    if out_len == 0 { return; }
    if ((out_len * ks) as u64) < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
        for i in 0..out_len {
            let mut acc = 0f64;
            for k in 0..ks { acc += x[i + k] * w[k]; }
            y[i] = acc;
        }
        return;
    }
    let q = out_len / 4;
    let s = [0, q, q+q, q+q+q, out_len];
    let yp = y.as_mut_ptr(); let xp = x.as_ptr(); let wp = w.as_ptr();
    struct SendMutPtr(*mut f64); struct SendConstPtr(*const f64);
    unsafe impl Send for SendMutPtr {} unsafe impl Send for SendConstPtr {}
    let yps = [SendMutPtr(yp), SendMutPtr(yp), SendMutPtr(yp), SendMutPtr(yp)];
    let xps = [SendConstPtr(xp), SendConstPtr(xp), SendConstPtr(xp), SendConstPtr(xp)];
    let wps = [SendConstPtr(wp), SendConstPtr(wp), SendConstPtr(wp), SendConstPtr(wp)];
    let [y0, y1, y2, y3] = yps;
    let [xp0, xp1, xp2, xp3] = xps;
    let [w0, w1, w2, w3] = wps;
    parallel_invoke_4(
        move || cv_chunk(y0, xp0, w0, ks, s[0], s[1]),
        move || cv_chunk(y1, xp1, w1, ks, s[1], s[2]),
        move || cv_chunk(y2, xp2, w2, ks, s[2], s[3]),
        move || cv_chunk(y3, xp3, w3, ks, s[3], s[4]),
    );
    #[inline(always)]
    fn cv_chunk(yp: SendMutPtr, xp: SendConstPtr, wp: SendConstPtr,
                ks: usize, i_start: usize, i_end: usize) {
        let yp = yp.0; let xp = xp.0; let wp = wp.0;
        for i in i_start..i_end {
            let mut acc = 0f64;
            for k in 0..ks { unsafe { acc += *xp.add(i + k) * *wp.add(k); } }
            unsafe { *yp.add(i) = acc; }
        }
    }
}

/// `dst[i] *= alpha` for all i
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_parallel_scale_f64")]
#[inline]
pub fn parallel_scale_f64(dst: &mut [f64], alpha: f64) {
    let n = dst.len();
    if n == 0 { return; }
    if (n as u64) < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
        for i in 0..n { dst[i] *= alpha; }
        return;
    }
    let q = n / 4;
    let q1 = q; let q2 = q + q1; let q3 = q + q2;
    let dp = dst.as_mut_ptr();
    struct SendMutPtr(*mut f64); unsafe impl Send for SendMutPtr {}
    let dp_a = SendMutPtr(dp);
    let dp_b = SendMutPtr(unsafe { dp.add(q1) });
    let dp_c = SendMutPtr(unsafe { dp.add(q2) });
    let dp_d = SendMutPtr(unsafe { dp.add(q3) });
    let len_d = n - q3;
    parallel_invoke_4(
        move || scl_chunk(dp_a, q, alpha),
        move || scl_chunk(dp_b, q, alpha),
        move || scl_chunk(dp_c, q, alpha),
        move || scl_chunk(dp_d, len_d, alpha),
    );
    #[inline(always)]
    fn scl_chunk(dp: SendMutPtr, n: usize, alpha: f64) {
        let dp = dp.0;
        for i in 0..n { unsafe { *dp.add(i) = *dp.add(i) * alpha; } }
    }
}

/// Elementwise `dst[i] = a[i] - b[i]`
#[doc(hidden)]
