    let dp_b = SendMutPtr(unsafe { dp.add(q1) });
    let dp_c = SendMutPtr(unsafe { dp.add(q2) });
    let dp_d = SendMutPtr(unsafe { dp.add(q3) });
    let ap_a = SendConstPtr(ap);
    let ap_b = SendConstPtr(unsafe { ap.add(q1) });
    let ap_c = SendConstPtr(unsafe { ap.add(q2) });
    let ap_d = SendConstPtr(unsafe { ap.add(q3) });
    let bp_a = SendConstPtr(bp);
    let bp_b = SendConstPtr(unsafe { bp.add(q1) });
    let bp_c = SendConstPtr(unsafe { bp.add(q2) });
