/// Squared-distance accumulate `dst[i] += (a[i] - b[i])^2`
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(not(test), rustc_diagnostic_item = "parallel_runtime_parallel_zip_diff_sq_add_f64")]
#[inline]
pub fn parallel_zip_diff_sq_add_f64(dst: &mut [f64], a: &[f64], b: &[f64]) {
    let n = core::cmp::min(dst.len(), core::cmp::min(a.len(), b.len()));
    if n == 0 { return; }
    if (n as u64) < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
        for i in 0..n {
            let v = a[i] - b[i];
            dst[i] += v * v;
        }
        return;
    }
    let q = n / 4;
    let q1 = q;
    let q2 = q + q1;
    let q3 = q + q2;
    let dp = dst.as_mut_ptr();
    let ap = a.as_ptr();
    let bp = b.as_ptr();
    struct SendMutPtr(*mut f64);
    struct SendConstPtr(*const f64);
    unsafe impl Send for SendMutPtr {}
    unsafe impl Send for SendConstPtr {}
    let dp_a = SendMutPtr(dp);
    let dp_b = SendMutPtr(unsafe { dp.add(q1) });
    let dp_c = SendMutPtr(unsafe { dp.add(q2) });
    let dp_d = SendMutPtr(unsafe { dp.add(q3) });
    let ap_a = SendConstPtr(ap);
    let ap_b = SendConstPtr(unsafe { ap.add(q1) });
    let ap_c = SendConstPtr(unsafe { ap.add(q2) });
    let ap_d = SendConstPtr(unsafe { ap.add(q3) });
    let bp_a = SendConstPtr(bp);
    let bp_b = SendConstPtr(unsafe { bp.add(q1) });
    let bp_c = SendConstPtr(unsafe { bp.add(q2) });
    let bp_d = SendConstPtr(unsafe { bp.add(q3) });
    let len_d = n - q3;
    parallel_invoke_4(
        move || dsa_chunk(dp_a, ap_a, bp_a, q),
        move || dsa_chunk(dp_b, ap_b, bp_b, q),
        move || dsa_chunk(dp_c, ap_c, bp_c, q),
        move || dsa_chunk(dp_d, ap_d, bp_d, len_d),
    );
    #[inline(always)]
    fn dsa_chunk(dp: SendMutPtr, ap: SendConstPtr, bp: SendConstPtr, n: usize) {
        let dp = dp.0; let ap = ap.0; let bp = bp.0;
        for i in 0..n {
            unsafe {
                let v = *ap.add(i) - *bp.add(i);
                *dp.add(i) = *dp.add(i) + v * v;
            }
        }
    }
}

// F32 versions of the elementwise helpers above

/// Closure-capable variant of `parallel_for_each_indexed_mut_f64`
#[doc(hidden)]
#[unstable(feature = "parallel_runtime_internal", issue = "none")]
#[cfg_attr(
    not(test),
    rustc_diagnostic_item = "parallel_runtime_parallel_for_each_indexed_mut_f64_dyn"
)]
#[inline]
pub fn parallel_for_each_indexed_mut_f64_dyn(
    dest: &mut [f64],
    body: &(dyn Fn(usize) -> f64 + Sync),
) {
    let n = dest.len();
    if n == 0 { return; }
    if (n as u64) < PARALLEL_REDUCE_THRESHOLD || !PARALLEL_RUNTIME_HAS_THREADS {
        for i in 0..n { dest[i] = body(i); }
        return;
    }
    let q = n / 4;
    let (s1, e1) = (0,         q);
    let (s2, e2) = (q,         q + q);
    let (s3, e3) = (q + q,     q + q + q);
    let (s4, e4) = (q + q + q, n);
    struct SendMutPtr(*mut f64);
    unsafe impl Send for SendMutPtr {}
    let dp1 = SendMutPtr(dest.as_mut_ptr());
    let dp2 = SendMutPtr(dest.as_mut_ptr());
    let dp3 = SendMutPtr(dest.as_mut_ptr());
    let dp4 = SendMutPtr(dest.as_mut_ptr());
    // Each closure captures `body` by reference
    parallel_invoke_4(
        move || dyn_chunk(dp1, body, s1, e1),
        move || dyn_chunk(dp2, body, s2, e2),
        move || dyn_chunk(dp3, body, s3, e3),
        move || dyn_chunk(dp4, body, s4, e4),
    );
    #[inline(always)]
    fn dyn_chunk(
        p: SendMutPtr,
        body: &(dyn Fn(usize) -> f64 + Sync),
        start: usize,
        end: usize,
    ) {
        let p = p.0;
        for i in start..end {
            let v = body(i);
            unsafe { *p.add(i) = v; }
        }
    }
}
